window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-12T20:03:56.527Z","stories":{"d01448e7-e6ef-4224-9e13-5f4b350dd6ed":{"publicId":"d01448e7-e6ef-4224-9e13-5f4b350dd6ed","title":"黄仁勋辞任英伟达CEO并退出董事会","status":"active","sourceCount":17,"reportCount":56,"firstReportAt":"2026-10-29T13:42:38.000Z","latestAt":"2026-11-12T18:39:23.000Z","latest":"黄仁勋辞职引发对 Nvidia 开源 AI 战略延续性的疑问","digest":"英伟达董事会11月12日宣布，联合创始人黄仁勋即刻辞去总裁、CEO及董事职务，结束逾33年执掌；首席财务官Colette Kress出任临时CEO，董事会已启动内外部继任者遴选，并任命前Synopsys CEO Harvey Jones为首任董事长。\n\n辞职源于《金融时报》报道他与新加坡数据中心公司Megaspeed高管Alice Huang的婚外情，美国情报界认为后者被中国国家安全部招募；黄仁勋随后向员工承认婚外情。董事会此前启动独立调查，称无理由认为国家安全或公司机密受损，但《华尔街日报》报道董事会已接近决定是否罢免他。\n\n事件还牵出芯片出口争议：Megaspeed被指采购数十亿美元英伟达芯片，并有报道称相关网络向中国买家转手硬件；黄仁勋辞职后，国会方面要求英伟达调整治理、收紧出口管制。","digestUpdatedAt":"2026-11-12T19:46:43.035Z","reports":[{"id":"ey8wwzav6ohoxh11jw491kcjg","title":"黄仁勋辞职引发对 Nvidia 开源 AI 战略延续性的疑问","summary":"Nvidia CEO 黄仁勋周四因承认与一名涉嫌中国间谍者的婚外情而辞职，引发对其开源 AI 支持路线能否延续的疑问。他此前推动 Nemotron 开源模型、支持收购 Hugging Face 的 130 亿美元交易，并牵头的 25 家公司联名信反对政府过度限制开源权重模型；CFO Colette Kress 已出任临时 CEO。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:39:23.000Z","url":"https://techcrunch.com/2026/11/12/jensen-huangs-exit-puts-nvidias-support-for-open-source-in-question/"},{"id":"n73ab4h9gqlu6ucv69ynzxln4","title":"SemiAnalysis 深度分析黄仁勋离开后的 Nvidia：一个为他量身打造的公司如何运转","summary":"SemiAnalysis 发文分析黄仁勋不再担任 Nvidia CEO 后的公司走向，认为其离职与 GPU 走私及国会推动的 RASA 出口管制法案有关。","sourceName":"SemiAnalysis 长文 RSS（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:06:26.000Z","url":"https://newsletter.semianalysis.com/p/nvidia-and-the-world-without-jensen"},{"id":"licdk6vosezxouovor3gvtcpe","title":"The Verge 分析黄仁勋辞职与 Nvidia 芯片走私疑云","summary":"The Verge 作者 Elizabeth Lopatto 分析 Nvidia 宣布黄仁勋辞职一事，认为第二桩婚外情只是导火索，真正原因或与芯片走私指控有关。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T17:44:33.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032069/jensen-huang-resignation-affair-chips-smuggling"},{"id":"rda6uss1k4k96ygzfl7a3byk0","title":"美众议院中国特设委员会主席 Moolenaar 就黄仁勋辞任 NVIDIA 发表声明","summary":"美众议院中国特设委员会主席 Rep. John Moolenaar 就黄仁勋辞任 NVIDIA 发表声明，称其被解职是一个本可避免的不幸结局。他表示 NVIDIA 现在必须改变公司治理方式，任命把国家安全置于最优先的领导层，并称国会应尽快在年底国防授权法案中通过两党出口管制立法。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T17:27:52.000Z","url":"https://x.com/rohanpaul_ai/status/2120931596396335208"},{"id":"sowwn4rv7ggtd41l0d469f1id","title":"Jensen Huang 被 Nvidia 董事会罢免 CEO 后，可能冲击 AI 行业的五个方面","summary":"Nvidia 董事会于周四罢免 CEO Jensen Huang，起因是他承认婚外情，且其中一名对象被美国政府怀疑为中国间谍、并任职于涉嫌走私 Nvidia 芯片的新加坡 neocloud。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:32:33.000Z","url":"https://techcrunch.com/2026/11/12/five-ways-jensen-huangs-ouster-from-nvidia-could-damage-the-ai-industry/"},{"id":"o8bau0c6koaa9ibvrxjfpl32e","title":"黄仁勋辞任英伟达CEO：中国究竟想从他身上得到什么？","summary":"黄仁勋辞去英伟达CEO职务，此前其与一名被指为中国间谍的女性存在关联的传闻持续发酵。布鲁金斯学会中国中心研究员Kyle Chan在Decoder访谈中分析，中国接近黄仁勋的重点可能不在GPU设计细节，而在于他对特朗普的直接影响力和美国政策制定过程的信息。访谈还讨论了DeepSeek R1、CUDA生态及华为等国产AI芯片替代路径。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:30:00.000Z","url":"https://www.theverge.com/podcast/1031260/nvidia-jensen-huang-resign-china-spy-scandal-ai-chips-trump"},{"id":"toq4wymx9maq8lhhz8jryi0sv","title":"黄仁勋辞职后，Nvidia 与 AI 热潮的未来走向分析","summary":"Azeem Azhar 分析黄仁勋辞任 Nvidia CEO 后的影响，CFO Colette Kress 将临时接任。他指出 Nvidia 五年间售出近 1400 万颗旗舰 AI 芯片、占市场 85%，并向 neocloud 提供财务担保、过去一年在欧洲投资近 100 亿美元；与乔布斯离任时不同，公司没有准备好的继任者，而黄仁勋本人一直是 AI 生态的关键纽带。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:19:28.000Z","url":"https://www.exponentialview.co/p/jensen-huang-and-the-future-of-the"},{"id":"jferw1o1blgp1kv5z4no8qb5s","title":"NVIDIA CEO 黄仁勋辞职，CFO Colette Kress 出任临时 CEO","summary":"NVIDIA 联合创始人黄仁勋于当天早晨辞去 CEO 和董事职务，此前董事会对其与直属下属的多段婚外情及一名涉嫌中国间谍的调查展开调查。董事会任命任职超过 13 年的 CFO Colette Kress 为临时 CEO，Harvey Jones 出任首任董事会主席并致信员工；Kress 在首封临时 CEO 信中称这是一段极其艰难的时期，公司将于 11 月 18 日 9am PT 举行全员会议。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T15:48:12.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032028/read-nvidias-internal-emails-jensen-huang"},{"id":"l7dv9twcz25784wh4ttbhxm78","title":"Nvidia CEO 黄仁勋辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia 董事会宣布，执掌公司 33 年的联合创始人兼 CEO 黄仁勋辞去总裁、CEO 及董事职务，即刻生效。辞职发生在媒体报道他与一名涉嫌中国间谍及其一位直接下属有婚外情之后，公司此前从未设立继任计划。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T15:37:29.000Z","url":"https://techcrunch.com/2026/11/12/jensen-huang-is-out-at-nvidia-who-is-colette-kress-his-interim-replacement/"},{"id":"xe5jgbho8qhh6ahx1353wdycv","title":"NVIDIA 官宣 CEO 过渡，发布声明链接","summary":"NVIDIA Newsroom 宣布 CEO 过渡，附官方新闻稿链接 https://nvidianews.nvidia.com/news/nvidia-announces-ceo-transition。转发者 X.PIN 仅以“Such an era!”感叹，未补充细节。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-12T14:59:46.000Z","url":"https://x.com/thexpin/status/2120894325370577402"},{"id":"aol3stj5rjrl9sq35s3d4fzt6","title":"《大西洋月刊》谈黄仁勋在华盛顿的影响力","summary":"《大西洋月刊》有篇有意思的文章。\n\n这期节目展示了黄仁勋的影响力在华盛顿扩散得有多广。\n\n据文章称，在报道公开前数月，警告就已传达至政府高层官员。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T14:53:11.000Z","url":"https://x.com/rohanpaul_ai/status/2120892671178973263"},{"id":"cq52ebt0mx19monojyqyuxdo1","title":"黄仁勋辞任 Nvidia CEO，CFO Colette Kress 接任临时负责人","summary":"Gary Marcus 称黄仁勋已辞去 Nvidia CEO 职务，董事会推动其离任，由 CFO Colette Kress 出任临时负责人。他表示消息公布后 Nvidia 股价跌幅从盘前 8% 扩大到开盘时的 13%，并担心黄仁勋主导的循环融资可能崩塌，以及此前承诺投入 Anthropic 的数十亿美元 IPO 资金是否兑现成为焦点。他同时列举了国会调查、中国市场影响和政治层面的后续不确定性。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:44:04.000Z","url":"https://garymarcus.substack.com/p/jensen-huang-resigns"},{"id":"m76r4bnrvb21vkm8wn2khk0jr","title":"Kate Clark 转发 WSJ 报道称 Nvidia 正准备罢免 CEO 黄仁勋并征集信源","summary":"记者 Kate Clark 分享 WSJ 报道链接，该报道称 Nvidia 正准备罢免 CEO 黄仁勋。她同时留下 Signal 联系方式 415-409-9095，征集关于此事对私募市场、交易撮合、融资及 AI 行业连锁影响的爆料与讨论。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-12T14:39:04.000Z","url":"https://x.com/KateClarkTweets/status/2120889116250288597"},{"id":"xraa42gmh7ndg2a3wvenh2rnv","title":"黄仁勋丑闻时间线：承认婚外情、辞去英伟达 CEO","summary":"英伟达联合创始人黄仁勋承认婚外情后，于 11 月 12 日辞去 CEO 一职，CFO Colette Kress 出任临时 CEO。此前有报道称其婚外情对象 Alice Huang 被美方怀疑为中国间谍，另一段与英伟达副总裁 Kimberly Powell 的婚外情也被《纽约时报》曝出。英伟达董事会已启动独立调查，美国国会还计划传唤黄仁勋作证。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:30:01.000Z","url":"https://techcrunch.com/2026/11/12/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"hfrol86d5xxs0jzhviul1dlof","title":"黄仁勋辞任 Nvidia CEO 并退出董事会，任职超 33 年","summary":"黄仁勋辞去 Nvidia CEO 并退出董事会，结束超过 33 年的执掌；CFO Colette Kress 出任临时 CEO，董事 Harvey Jones 成为 Nvidia 首位董事会主席。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T14:16:34.000Z","url":"https://x.com/rohanpaul_ai/status/2120883455689170968"},{"id":"a8s824c3xp0bij54fi8q9psm7","title":"黄仁勋因间谍丑闻辞去 Nvidia CEO 职务，公司市值蒸发 1.4 万亿美元","summary":"黄仁勋于 2026 年 11 月 12 日立即辞去 Nvidia CEO、总裁及董事会成员职务，此前《华尔街日报》报道董事会因两段婚外情（其中一段涉及疑似中国间谍）计划将其解雇。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:11:40.000Z","url":"https://the-decoder.com/jensen-huang-resigns-as-nvidia-ceo-after-espionage-scandal-wipes-out-1-4-trillion-in-market-value/"},{"id":"b79vyi335xo1r2u8eiza66a8r","title":"Nvidia CEO 黄仁勋因绯闻与间谍丑闻辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia 董事会宣布，联合创始人、总裁兼 CEO 黄仁勋在两段婚外情报道曝光后辞职，即日生效，自 2013 年起任职的 CFO Colette Kress 被任命为临时 CEO，并任命前 Synopsys CEO Harvey C. Jones 为公司历史上首任董事长。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T13:53:16.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031689/jensen-huang-nvidia-ceo-resigns"},{"id":"qsbjbz754aodhcijq56puh6va","title":"NVIDIA 宣布 CEO 变动：Jensen Huang 辞任，CFO Colette Kress 出任临时 CEO","summary":"NVIDIA 董事会宣布 Jensen Huang 即刻辞去总裁、CEO 及董事职务，CFO Colette Kress 被任命为临时 CEO，直至选定永久继任者，董事会已启动内外部人选遴选。","sourceName":"NVIDIA：Newsroom（RSS）","firstParty":true,"publishedAt":"2026-11-12T13:48:00.000Z","url":"https://nvidianews.nvidia.com/news/nvidia-announces-ceo-transition"},{"id":"mo0q79b9m2krn2wunnm5blw48","title":"郭明錤谈黄仁勋出轨丑闻：英伟达或需降低对其决策依赖并布局接班计划","summary":"天风国际分析师郭明錤在 X 平台发文评黄仁勋出轨丑闻，认为黄的价值在于把工程团队认为可行的技术转化为全公司愿意投入资源、承担风险并交付的产品，带动供应链订单能见度与竞争对手跟进。他从公开信息判断黄仁勋似乎很难全身而退，建议英伟达阶段性降低对黄个人的决策依赖并布局接班计划，其后续新品研发效率与竞争对手回应将是观察 AI 产业发展和投资趋势的重点。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T04:15:28.377Z","url":"https://www.ithome.com/1/026/027.htm"},{"id":"b0is4k552g0vme6l74e8z1lhw","title":"Gary Marcus 评 WSJ 报道 Nvidia 正准备解雇 CEO 黄仁勋","summary":"Gary Marcus 引述《华尔街日报》报道称，Nvidia 正准备解雇 CEO 黄仁勋，起因是公司调查其与一名被指为中国间谍的女性的婚外情。作者认为黄仁勋是整个循环融资的主导者，若其离任这些安排可能崩塌，并质疑代理 CEO 是否会兑现 Nvidia 承诺给 Anthropic 的数十亿美元 IPO 投资；盘后股价已下跌。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-11T23:53:06.000Z","url":"https://garymarcus.substack.com/p/jensen-is-reportedly-about-to-get"},{"id":"i1hiziogjyvjvclikqylj5p2p","title":"黄仁勋丑闻时间线：婚外情、疑似中国间谍与Nvidia董事会罢免传闻","summary":"Nvidia CEO 黄仁勋公开承认婚外情，其绯闻对象、Megaspeed 高管 Alice Huang 被美国官员怀疑是中国间谍。纽约时报称黄仁勋还与直接向他汇报的 Nvidia 医疗健康副总裁 Kimberly Powell 存在婚外关系，Nvidia 董事会正准备罢免他，股价盘后下跌。国会计划传唤黄仁勋就此事作闭门说明。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T23:50:00.000Z","url":"https://techcrunch.com/2026/11/11/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"aoxmmcsudy1gf9xmti7slu1wd","title":"WSJ 报道 Nvidia 董事会接近决定是否罢免 CEO 黄仁勋","summary":"WSJ 报道，Nvidia 董事会此前公开支持黄仁勋，如今接近决定是否罢免这位创始人 CEO。起因是黄仁勋与一名被指为中国情报人员的女子交往，随后又曝出与一名 Nvidia 员工的第二段婚外情；周日开始独立调查时董事会表示没有理由认为 Nvidia 机密泄露。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T23:43:05.000Z","url":"https://x.com/rohanpaul_ai/status/2120663635479625930"},{"id":"vyp3tt502r42oxb18k4b663hi","title":"黄仁勋\"蜜罐\"丑闻背后：半导体行业高管行为问题是否更普遍？","summary":"Heron Intelligence CEO Nate Singer 在黄仁勋\"蜜罐\"丑闻后表示，半导体行业存在多起未曝光的类似高管行为案例，他已看到至少三份相关报告，并怀疑更多案例未被上报。Singer 称业内许多高管知晓此类行为却实际上予以纵容，涉事人员\"已嵌入这些公司\"。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T16:16:07.000Z","url":"https://techcrunch.com/2026/11/11/is-jensen-huangs-bad-behavior-more-commonplace-than-it-seems/"},{"id":"x7y9eom67zy7rs1vzn6sijizd","title":"ElevenLabs 纽约峰会发布多项更新：Interaction Engine、ElevenAgents 升级与 ElevenAI","summary":"ElevenLabs 在纽约峰会宣布多项发布，定位为构建 AI 的交互层。","sourceName":"ElevenLabs：Blog（网页）","firstParty":true,"publishedAt":"2026-11-11T12:00:00.000Z","url":"https://elevenlabs.io/blog/nyc-summit"},{"id":"k0s9asp7ahp38drtj69gi5lye","title":"英伟达CEO绯闻或波及芯片业","summary":"《华尔街日报》：出口管制支持者以这一事件为证，佐证他们对漏洞的警告\n\n“英伟达CEO的绯闻可能给这家全球顶级芯片设计公司乃至整个行业带来商业后果。\n\n尽管许多议员在提出法案时都提到了英伟达，但这些提案可能伤及其他芯片公司，包括英伟达的竞争对手AMD，甚至微软和OpenAI这类正试图在海外建设数据中心的科技巨头。”","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T05:42:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120391599264063648"},{"id":"ggty0pffnixa85pbbyxk826ug","title":"FT 曝 Alice Huang 借 Megaspeed 走私 Nvidia 芯片","summary":"FT 发文披露 Alice Huang 与秘密男友兼商业伙伴 Kang Wei 运营新加坡公司 Megaspeed，用阿里巴巴的资金向被美国出口规则限制的中国客户出租 Nvidia 芯片。她改名 Alice Wong 并把妹妹安插进公司董事会以隐藏实际控制人，美国情报部门认为她在接近黄仁勋期间为中国从事间谍活动，新加坡调查 Megaspeed 芯片走私后她已消失。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T20:28:14.000Z","url":"https://x.com/rohanpaul_ai/status/2120252212551332311"},{"id":"lmoed4ffl87b0bpfvt1lzsp1g","title":"黄仁勋被曝与疑似中国间谍有染，或危及美国 AI 领先地位","summary":"英伟达 CEO 黄仁勋承认与一名疑似中国间谍的女性有染，事件可能冲击整个美国 AI 产业并危及国家安全。专家向 The Verge 表示，若中国借此获得英伟达芯片，美国在 AI 上的领先优势\"可能在数周或数月内消失\"；与这名疑似间谍有关联的公司据称已促成至少 70 亿美元的英伟达芯片销往中国。消息曝光后英伟达股价下跌。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T19:04:05.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031063/jensen-huang-ai-race-us-china-spy"},{"id":"gqzca7y2h3m9p0fxtj60m4i1t","title":"Ed Zitron 长文剖析黄仁勋丑闻与 NVIDIA 疑似借 Megaspeed 向中国走私 GPU","summary":"Ed Zitron 长文梳理黄仁勋承认与 Megaspeed CEO Alice Huang 的婚外情事件，并整合 Bloomberg、纽约时报、金融时报与 Culper Research 的报道，指 Megaspeed 疑似作为转口实体将 NVIDIA GPU 非法流入中国。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-10T17:43:27.000Z","url":"https://www.wheresyoured.at/jensens-bizarre-adventure/"},{"id":"nakew5hejxet8jnydy0h37b1q","title":"英伟达 CEO 黄仁勋承认婚外情，涉疑似中国间谍事件时间线","summary":"英伟达 CEO 黄仁勋 11 月 8 日向员工公开承认婚外情，并称此事关联新闻报道中的国家安全担忧，英伟达董事会已启动独立调查，公司股价次日下跌超 5%。美方官员认为其婚外情对象、Megaspeed 高管 Alice Huang 为中国间谍，Megaspeed 过去两年据称采购了 48 亿美元英伟达芯片。三名共和党委员会主席已要求黄仁勋就中国获取美国技术风险进行闭门简报。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T17:04:19.000Z","url":"https://techcrunch.com/2026/11/10/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"f1z5v9nswvnu4w2plxd4tg22t","title":"The Information 报道称与英伟达 CEO 黄仁勋相关人士向中国买家转手 75 亿美元硬件","summary":"据 The Information 报道，与英伟达 CEO 黄仁勋有染的 Alice Huang（无亲属关系）与丈夫和姐姐在中国和新加坡建立采购网络，涉资 75 亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T14:33:22.000Z","url":"https://x.com/rohanpaul_ai/status/2120162909422780789"},{"id":"z68n80gno9fz2iwdgj4wr9tyw","title":"黄仁ullah承认婚外情，Nvidia 董事会调查对方是否为中国国安部工作","summary":"周日黄仁ullah向全体 Nvidia 员工发邮件承认与 Megaspeed 高管 Alice Huang 的婚外情，其董事会已启动调查，核查该女士是否为中国国家安全部工作。Megaspeed 这家被怀疑向中国走私 Nvidia 芯片的新加坡云公司仍在继续采购芯片。","sourceName":"ChinaTalk（RSS）","firstParty":false,"publishedAt":"2026-11-10T12:28:08.000Z","url":"https://www.chinatalk.media/p/the-spy-who-leased-me"},{"id":"kci32x4hgxrdl0v5o4xrjlxri","title":"The Verge 梳理黄仁勋与 Megaspeed 高管丑闻对 Nvidia 出口管制游说的影响","summary":"The Verge 依据《纽约时报》等报道梳理 Nvidia CEO 黄仁勋与新加坡云服务商 Megaspeed 高管 Alice Huang 的婚外情风波。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:51:58.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030328/what-could-china-get-from-jensen-huang"},{"id":"t5mqlkgq1zlspdsk77jrx1ho5","title":"Trump 就间谍指控表态支持 Nvidia CEO 黄仁勋","summary":"Trump 在与 Nvidia CEO 黄仁勋就间谍指控谈话后公开为其辩护，称黄仁勋告诉他从不认识那名女性是间谍，并表示相信他。Trump 称黄仁勋是高素质的人，提到其芯片领先十年、因复杂度难以被复制，并称相信黄仁勋因家人而深感痛苦。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T23:12:09.000Z","url":"https://x.com/rohanpaul_ai/status/2119931075325759514"},{"id":"lzsihkjga6ini01aqrzcuvtaw","title":"Nvidia CEO 黄仁勋因婚外情与涉华间谍报道辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia CEO、总裁兼联合创始人黄仁勋在承认与 Megaspeed 高管 Alice Huang 的婚外情后辞职，CFO Colette Kress 出任临时 CEO。《纽约时报》周三报道称，还有证据显示黄仁勋与一名直接向他汇报的 Nvidia 高管存在另一段婚外情，当晚董事会会议以黄仁勋辞职告终。此前有报道称，美国情报部门自去年起认定 Alice Huang 为中国国家安全部间谍。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:07:59.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030422/nvidia-jensen-huang-ai-china-alice-huang"},{"id":"zqvokl37rwbvoxzfk3c2v7964","title":"做空机构 Culper Research 曾在丑闻爆发前六个月提示 Nvidia CEO 与疑似中国间谍的关系","summary":"Nvidia 间谍丑闻爆发前六个月，做空机构 Culper Research 已在 5 月 13 日报告中质疑 CEO 黄仁勋与 Megaspeed 高管 Alice Huang 关系“异常密切”。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T22:46:09.000Z","url":"https://techcrunch.com/2026/11/09/a-short-seller-flagged-nvidia-ceos-ties-to-a-suspected-chinese-spy-six-months-before-the-scandal/"},{"id":"wtp3nz2jg6cfwlvn12lqrucy7","title":"黄仁勋因个人风波退出 ElevenLabs Summit 等演讲活动","summary":"TechCrunch 报道，Nvidia CEO 黄仁勋退出本周三在纽约举行的 ElevenLabs Summit，并取消了包括 Anthropic CEO Forum 在内的其他演讲安排，ElevenLabs 周一已确认。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T20:09:06.000Z","url":"https://techcrunch.com/2026/11/09/jensen-huang-pulls-out-of-elevenlabs-summit-amid-nvidia-controversy/"},{"id":"jg700hxd681xxb0f0r5fn03fc","title":"黄仁勋与疑似中国间谍的婚外情令 Nvidia 中国业务承压","summary":"《金融时报》报道 Nvidia CEO 黄仁勋与 Nvidia 客户 Megaspeed 前高管 Alice Huang 存在婚外情，美国情报官员认为后者被中国情报部门招募以影响芯片出口限制。黄仁勋已承认此事并向公司致歉，Nvidia 独立董事正联合外部律师调查，国会也要求作出解释。截至 7 月 26 日的三个月内，Nvidia 来自中国总部客户的收入为 79 亿美元，约占总营收 8%。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T18:09:52.000Z","url":"https://techcrunch.com/2026/11/09/jensen-huangs-affair-with-alleged-chinese-spy-puts-nvidias-china-ambitions-under-scrutiny/"},{"id":"q8qzxski2nw3jgr77q1mwpskg","title":"Nvidia CEO 黄仁勋陷间谍丑闻风波：The Verge 分析其公司结构与 AI 生态风险","summary":"The Verge 作者评述 The New York Times 报道的 Nvidia CEO 黄仁勋与 Megaspeed 高管 Alice Huang 的关系风波，后者被指被中国国家安全部招募，Megaspeed 曾购买 48 亿美元被限制出口的 Nvidia 芯片。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T17:36:08.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1029990/jensen-huang-the-spy-who-loved-me"},{"id":"mkmn0bduza8asy7b56mygydl2","title":"Nvidia CEO 黄仁勋承认婚外情，董事会启动独立调查","summary":"Nvidia CEO 黄仁勋在内部信中承认婚外情，此前 FT 报道称美国情报界认为其涉事对象 Alice Huang 为中国国家安全部招募的间谍。Nvidia 董事会将启动独立调查，称无理由认为国家安全或公司机密受损，黄仁勋承诺全力配合。Nvidia 法兰克福上市股票周一早盘跌超 6%。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T15:23:20.000Z","url":"https://arstechnica.com/tech-policy/2026/11/ceo-jensen-huang-admits-affair-as-nvidia-probes-possible-chinese-espionage/"},{"id":"cqmkdswfcbyr8hd49dj0ek3b8","title":"黄仁勋被指陷入蜜罐事件后，英伟达董事会展开调查","summary":"Big Technology 分析黄仁勋承认与美方情报机构认为是中方间谍的 Alice Huang 有染后，英伟达董事会已就是否泄露国家和公司机密展开调查，黄仁勋暂留任 CEO。文章认为这不只是私人丑闻，还可能削弱他在放宽对华芯片出口管制上的游说公信力，并给 Anthropic 和 Google 留出机会，同时反 AI 的民主党人可能在国会听证中以他为首个目标；中国否认相关指控。","sourceName":"Big Technology（热点 RSS）","firstParty":false,"publishedAt":"2026-11-09T15:11:49.000Z","url":"https://www.bigtechnology.com/p/the-jensen-huang-honeypot-fallout"},{"id":"xxxpa0kcnhfiyb59ylopto1y7","title":"Gary Marcus 评论：黄仁勋为对华芯片销售辩护或成其最大风险","summary":"Gary Marcus 认为，真正让黄仁勋陷入麻烦的不是他与 Alice Huang 的照片和视频，而是他近期在多次采访中持续为中国购买 Nvidia 芯片的权利辩护，几乎像中国的说客。文章还提到相关照片据称由 Alice Huang 从其微信朋友圈分享。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-09T12:47:02.000Z","url":"https://garymarcus.substack.com/p/jensen-is-cooked"},{"id":"e17dl64mjiov57c0jtwn41bxd","title":"Nvidia CEO 黄仁勋婚外情风波削弱其对严格 AI 芯片出口管制的游说","summary":"据 Bloomberg 报道，Nvidia CEO 黄仁勋在全员备忘录中承认与被美国情报机构认定为疑似中国情报人员线人的 Alice Huang（Huang Le）存在婚外关系，董事会已启动独立董事主导的调查。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-09T11:38:43.000Z","url":"https://the-decoder.com/nvidia-espionage-scandal-weakens-huangs-lobby-against-tighter-ai-chip-export-controls/"},{"id":"i8df3mmfly47axpbbr1p6ivh5","title":"耶鲁教授 Sonnenfeld 估计黄仁勋职位去留概率约为 50-50","summary":"Nvidia 董事会宣布对 CEO 黄仁勋启动独立调查后，TechCrunch 采访耶鲁教授 Jeffrey Sonnenfeld，他估计黄仁勋保住职位的概率约为 50-50。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T05:26:29.000Z","url":"https://techcrunch.com/2026/11/08/is-jensen-huangs-job-on-the-line-yales-jeffrey-sonnenfeld-estimates-its-about-a-50-50/"},{"id":"vde0trttubiyy6ilx0r7s13xj","title":"Gary Marcus 评黄仁勋婚外情风波：谁在何时知情","summary":"Gary Marcus 撰文称，黄仁勋在致 Nvidia 员工的信中承认与涉芯片业务的 Alice Huang 有婚外情，作者转述其涉嫌中国间谍与芯片走私的说法属未经证实的指控。文中梳理国会拟调查、Rubio 备忘录、Nvidia 此前否认等各方知情情况，并指出 Nvidia 期货下跌且无明确接班计划，事件可能冲击 AI 投资市场。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-09T02:04:38.000Z","url":"https://garymarcus.substack.com/p/the-huang-affair-what-did-they-know"},{"id":"c68qgzkcml50onal4kyn5t3lf","title":"NYT 报道 Nvidia 调查黄仁勋与一名中国间谍的关系","summary":"Rohan Paul 转述 NYT 报道称，Nvidia 首席执行官黄仁勋周日承认与美国官员认定为中国情报部门工作的一名企业高管有亲密关系。该高管 Alice Huang 领导新加坡数据中心公司 Megaspeed，自 2024 年 6 月以来购买了超过 $4.8B 的 Nvidia 芯片，美国官员一年多前开始监视她，调查其是否协助向中国走私受限 AI 芯片；今年春天由国务卿 Marco Rubio 主导起草的机密备忘录称，中国国家安全部招募她来接近黄仁勋。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T01:47:44.000Z","url":"https://x.com/rohanpaul_ai/status/2119607842487627887"},{"id":"serfp8560yfwla4o72g7d8voo","title":"NVIDIA 董事会声明：就黄仁勋被指为外国情报活动目标启动独立调查","summary":"针对近期有报道称创始人兼 CEO 黄仁勋已成为外国情报活动的目标，NVIDIA 董事会宣布启动独立调查，由独立董事组成的委员会监督并聘请外部独立法律顾问协助。董事会表示目前没有理由认为国家安全或公司机密信息已遭损害，黄仁勋完全支持此次审查并承诺配合。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-08T21:58:05.000Z","url":"https://x.com/indigox/status/2119550049013153901"},{"id":"mg4znyraf1xbbwg1vd915wqoi","title":"NVIDIA 董事会宣布就 CEO 黄仁勋遭外国情报行动瞄准一事启动独立调查","summary":"NVIDIA 董事会于 11 月 8 日发布声明，就近期有关创始人兼 CEO 黄仁勋成为外国情报行动目标的报道启动独立调查。调查由独立董事组成的委员会在外部独立律师协助下监督，黄仁勋全力配合。董事会表示没有理由认为国家安全或 NVIDIA 机密已受损，但调查将审视所有可用信息，并表示对黄仁勋及其领导团队有信心。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-08T21:21:17.000Z","url":"https://x.com/rohanpaul_ai/status/2119540787147059491"},{"id":"envwqgu0h1bp0si2xxbu66rz2","title":"Nvidia 董事会宣布独立调查 CEO 黄仁勋与疑似中国间谍的关系","summary":"Nvidia 董事会周日宣布，就 CEO 黄仁勋与新加坡芯片公司 Megaspeed 高管 Alice Huang 关系的报道启动独立调查。Bloomberg 等媒体报道称，一份在美国政策制定者间流传的备忘录声称 Alice Huang 被中国国家安全部招募、以刺探黄仁勋；黄仁勋在内部备忘录中承认婚外情并致歉。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-08T21:00:11.000Z","url":"https://techcrunch.com/2026/11/08/nvidia-says-its-investigating-ceo-jensen-huangs-relationship-with-possible-chinese-spy/"},{"id":"prq12tygrxswzhfanvbywdi4b","title":"Nvidia 董事会对 CEO 黄仁勋与疑为中国间谍的 Megaspeed 高管关系展开独立调查","summary":"Nvidia 董事会宣布对 CEO 黄仁勋启动独立调查，缘于其与 Megaspeed 高管 Alice Huang 的密切关系；报道称她被中国国家安全部招募充当间谍。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-08T20:22:39.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1029562/nvidia-investigating-jensen-huang-relationship-chinese-spy"},{"id":"rd1dy24n73w7u5c3lgxeletvo","title":"NY Times 报道称中国招募 AI 高管 Alice Huang 接近 Nvidia 黄仁勋从事情报活动","summary":"NY Times 报道，一份在特朗普政府高级官员间传阅的备忘录称，美国情报机构认定与中国国家安全部有关联的高管 Alice Huang 是北京的间谍资产，被招募来研究美国芯片并可能影响 Nvidia。其公司 Megaspeed 于 2024 年启动数十亿美元的 Nvidia 芯片采购，并向阿里巴巴出租东南亚数据中心算力，为中国提供获取受限芯片的后门。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-08T19:27:36.000Z","url":"https://x.com/rohanpaul_ai/status/2119512179733061681"}]},"2ff1f46f-7e98-4965-a5b2-87329632ca5d":{"publicId":"2ff1f46f-7e98-4965-a5b2-87329632ca5d","title":"Google 发布 Gemini 4 Hydrogen，接入搜索与编程工具","status":"active","sourceCount":19,"reportCount":33,"firstReportAt":"2026-11-11T16:00:00.000Z","latestAt":"2026-11-12T19:27:45.000Z","latest":"Google 发布 Gemini 4 Hydrogen 并将其接入 Search 提升复杂问题回答","digest":"Google DeepMind 发布 Gemini 4 Hydrogen，定位为快速执行日常编码与智能体工作流的模型，与主打深度推理的 Carbon、Argon 同属 Gemini 4 系列。Google 称这是 Search 迄今最大的模型升级，已向全球所有用户开放于 Google Search；该模型同时成为 Gemini Managed Agents 中 Antigravity 智能体的默认模型，并已上线 Cursor 和 Cognition 的 Devin Desktop、Devin CLI。Ars Technica 称它取代了此前广泛使用的 Gemini 3.8 Flash，且上线即开放，不像 Argon、Carbon 那样分阶段推送。\n\n使用范围按用户类型区分：所有用户可在 Gemini 应用、Google Search 和 Google AI Studio 访问；付费 Google AI Pro 和 Ultra 订阅者还可在 Google Antigravity、Chrome 中的 Gemini 和 Google Sheets 中的 Gemini 使用；开发者和企业可通过各档 Gemini API、Android Studio 及 Gemini for business 使用。免费用户在 Gemini 应用中需通过自动模型选择，在适合该提示词的场景下才会用到 Hydrogen。定价为 100 万 token 上下文窗口内统一计价：输入每百万 token 1.50 美元，输出每百万 token 7.50 美元。\n\n第三方评测机构 Artificial Analysis 称，该模型新增的 xhigh 推理档在 Intelligence Index 得 54 分，比 Claude Sonnet 5.5 (max) 和 GPT-6.1 Sol (max) 低 1 分；每任务成本约为 Sonnet 的 32%，但约为 GPT-6.1 Sol 的 2.5 倍。Cursor 称该模型在其默认 effort 下 CursorBench 得分 54.3%，高于 Gemini 3.8 Flash 的 39.6%；Cognition 称其在 FrontierCode 2.0 得 38.2%，仅次于 GPT-6.1 Sol；Arena 榜单显示 Gemini 4 Hydrogen (High) 首次进入 Code Arena: WebDev 第 10 名，得 1703 分。","digestUpdatedAt":"2026-11-12T19:49:13.737Z","reports":[{"id":"glx90o1i9stshq4vwsxdsguy5","title":"Google 发布 Gemini 4 Hydrogen 并将其接入 Search 提升复杂问题回答","summary":"Google 发布 Gemini 4 Hydrogen 模型并将其接入 Search，称这是 Search 迄今最大的一次模型改进。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T19:27:45.000Z","url":"https://techcrunch.com/2026/11/12/googles-latest-search-upgrade-promises-better-answers-to-your-most-complicated-questions/"},{"id":"w1u3ixmq8qb8g20v2o8yfebpw","title":"Google 在搜索中引入 Gemini 4 Hydrogen","summary":"Google 官方宣布 Gemini 4 Hydrogen 已进入 Google Search，并提供链接 goo.gle/4AqQVF5 供用户了解更多信息。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T19:23:35.000Z","url":"https://x.com/Google/status/2120960717071474748"},{"id":"pplqpkkb0a59joi6llhtmrgff","title":"Google Search 接入 Gemini 4 Hydrogen 并向全球用户推送","summary":"Google 宣布 Search 迎来迄今最大模型更新，接入 Gemini 4 Hydrogen，今日起向全球所有用户推出。更新包括更好理解多部分复杂问题、支持错别字并覆盖所有 AI Mode 语言；回答采用带图片、对比表的视觉化布局；升级 query fan-out，并行子主题查询以链接更多相关网页。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T19:23:34.000Z","url":"https://x.com/Google/status/2120960715011883148"},{"id":"r03z6qalcfw99hwf8jq8b5mxb","title":"Google 发布 Gemini 4 Hydrogen，取代 Gemini 3.8 Flash","summary":"Google 发布 Gemini 4 Hydrogen，取代生态内广泛使用的 Gemini 3.8 Flash，且开放程度远高于此前 Argon、Carbon 的分阶段策略，上线即对用户开放。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T19:23:03.000Z","url":"https://arstechnica.com/google/2026/11/google-rolls-out-gemini-4-hydrogen-finally-replacing-3-8-flash/"},{"id":"o8coj46233j11jhise87m8gza","title":"Gemini 4 Hydrogen (High) 登上 Code Arena: WebDev 第 10 名，得 1703 分","summary":"Arena 官方榜单显示，Google DeepMind 的 Gemini 4 Hydrogen (High) 首次进入 Code Arena: WebDev 排行第 10 名。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-12T19:05:40.000Z","url":"https://x.com/arena/status/2120956209725661670"},{"id":"qcfuv50f2bxz6tv32dtblc88x","title":"谷歌发布 Gemini 4 Hydrogen 模型，主打日常编程与智能体工作流","summary":"谷歌推出 Gemini 4 Hydrogen 模型，面向日常编码和智能体工作流，输入每百万 Tokens 1.50 美元、输出 7.50 美元，覆盖 100 万 Token 上下文无阶梯计价。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T18:50:00.073Z","url":"https://www.ithome.com/1/026/446.htm"},{"id":"uu2pim7p0lb9lhqcrvg7v3zgu","title":"Gemini 4 Hydrogen 上线 Devin","summary":"Gemini 4 Hydrogen 现已在 Devin Desktop 和 Devin CLI 上线。\n\n在 FrontierCode 2.0 上——这是我们用来基于质量和可合并性评估模型在真实工程任务中表现的基准——Gemini 4 Hydrogen 得分 38.2%，仅次于 GPT-6.1 Sol。","sourceName":"X：Cognition (@cognition)","firstParty":false,"publishedAt":"2026-11-12T18:44:28.000Z","url":"https://x.com/cognition/status/2120950876248641588"},{"id":"mt013742fhedisepp2i31h1r4","title":"Gemini 4 Hydrogen 上线 Cursor，CursorBench 得分 54.3%","summary":"作者以「爱好包括制作 og:images」调侃，配图为 CursorBench 4.0 的模型散点图；其引用 Cursor 官方内容称 Gemini 4 Hydrogen 现已在 Cursor 上线，默认 effort 下 CursorBench 得分 54.3%，高于 Gemini 3.8 Flash 的 39.6%。","sourceName":"X：Matt Palmer（SpaceXSI，Grok Bot） (@mattyp)","firstParty":false,"publishedAt":"2026-11-12T18:22:08.000Z","url":"https://x.com/mattyp/status/2120945253666762973"},{"id":"leysijsx8660t8pwgnnslip9g","title":"Cursor 公布 Gemini 4 Hydrogen 定价","summary":"Gemini 4 Hydrogen 定价为每百万输入 token 1.50 美元，每百万输出 token 7.50 美元。\n\n对比各档 effort 水平：https://cursor.com/evals?v=1","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-12T18:19:44.000Z","url":"https://x.com/cursor_ai/status/2120944651960291781"},{"id":"vwpr1h68drk55b95gmxib4f4q","title":"Gemini 4 Hydrogen 现已登陆 Cursor，CursorBench 得分 54.3%","summary":"Cursor 宣布 Gemini 4 Hydrogen 现已可用。其默认 effort 下在 CursorBench 得分 54.3%，高于 Gemini 3.8 Flash 的 39.6%。","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-12T18:19:41.000Z","url":"https://x.com/cursor_ai/status/2120944639633211619"},{"id":"q7eh6zetx4dgeec6vz7r00onv","title":"Gemini 4 Hydrogen 发布，已上线 Gemini App","summary":"Google Labs VP Josh Woodward 宣布发布 Gemini 4 Hydrogen，现已可在 Gemini App 中使用。原文称该模型速度快、更智能、是一次大幅提升，未给出具体性能数据或技术细节。","sourceName":"X：Josh Woodward (@joshwoodward, Google Labs VP)","firstParty":false,"publishedAt":"2026-11-12T18:10:15.000Z","url":"https://x.com/joshwoodward/status/2120942262054232392"},{"id":"e3o0ut2he1m7y82w20od4ed48","title":"Gemini 4 Hydrogen 任务速度提升 2.5 倍","summary":"仅作一项对比，Gemini 4 Hydrogen 完成任务的速度比 3.8 Flash 快 2.5 倍，同时智能程度高得多，编造内容还少了 5 倍。\n\n这是个好模型 ：)","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-12T18:09:12.000Z","url":"https://x.com/OfficialLoganK/status/2120941998014390392"},{"id":"w3iirjuk8jtt1lka51a28bwv2","title":"Gemini 4 Hydrogen 开始向所有人推送，覆盖 Gemini App、搜索与 Gemini API","summary":"Google 宣布 Gemini 4 Hydrogen 即日起开始推送。所有用户可在 Gemini App、Google Search 和 Google AI Studio 使用；AI Pro 和 Ultra 订阅者还可用于 Antigravity、Chrome 中的 Gemini 和 Google Sheets 中的 Gemini；开发者和企业可在 Google AI Studio、AndroidStudio 及各档 Gemini API 使用。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:10.000Z","url":"https://x.com/Google/status/2120941989948457042"},{"id":"t1zssrg26pwcowrqz6buo5qp9","title":"Google 发布 Gemini 4 Hydrogen：智能、速度与可靠性大幅提升","summary":"Google 发布 Gemini 4 Hydrogen，称其在默认 high thinking 下于 Artificial Analysis 智能指数上超过 Argon，xhigh 下更高，且同类任务完成更快。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:09.000Z","url":"https://x.com/Google/status/2120941986895319158"},{"id":"clge7zh429cqvd5tz2zsr908w","title":"Google 发布 Gemini 4 Hydrogen，主打日常编码与智能体工作","summary":"Google 发布 Gemini 4 Hydrogen，面向日常编码和智能体工作，强调速度与效率。该模型提供 4 个思考级别，可独立使用或与 Carbon 和 Argon 协同，比 3.8 Flash 快 2.5X，官方称在其同级中领先竞争模型。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:08.000Z","url":"https://x.com/Google/status/2120941982004523367"},{"id":"mlams5mulqbf16g7tini41vf3","title":"Google 介绍 Hydrogen 四档思考级别与 Antigravity Orchestrator 多模型协作","summary":"Google 介绍 Hydrogen 提供低、中、高和新增 xhigh 四个思考级别，按可预期的方式权衡智能、延迟和 token 用量。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:08.000Z","url":"https://x.com/Google/status/2120941984148041901"},{"id":"ajvxvhu8bh001pourbhhjl0ir","title":"Artificial Analysis 评测 Gemini 4 Hydrogen：智能指数 54，接近 Sonnet 5.5 且成本约其 32%","summary":"Artificial Analysis 评测 Google 新发布的 Gemini 4 Hydrogen：新增 xhigh 推理档在 Intelligence Index 得 54 分，比 Claude Sonnet 5.5 (max) 和 GPT-6.1 Sol (max) 低 1 分，每任务成本约为 Sonnet 的 32%，但约为 GPT-6.1 Sol 的 2.5 倍。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-12T18:07:16.000Z","url":"https://x.com/ArtificialAnlys/status/2120941511223185722"},{"id":"psfuehcy5xg07khe2ggyazuhq","title":"Google 发布 Gemini 4 Hydrogen，与 Carbon、Argon 一起开启 Gemini 4 时代","summary":"Google 发布 Gemini 4 Hydrogen，与 Carbon 和 Argon 一起完整开启 Gemini 4 时代。作者 Logan Kilpatrick 表示自己已每日使用该模型，Google 内部有数千人也在使用，并给出博客链接 https://blog.google/innovation-and-ai/models-and-research/gemini-models/introducing-gemini-4-hydrogen/。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-12T18:06:55.000Z","url":"https://x.com/OfficialLoganK/status/2120941424028029030"},{"id":"ybgw60e8kl0ckmqzx8x4n18q6","title":"Gemini 4 Hydrogen 开始向全球所有用户推送","summary":"Google Gemini 宣布 Gemini 4 Hydrogen 今日开始向全球所有用户推送，覆盖桌面、移动端和网页。免费用户可通过自动模型选择在适合该提示词的场景下使用 Gemini 4 Hydrogen，详情见 https://goo.gle/4AxH40q。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:06:49.000Z","url":"https://x.com/GeminiApp/status/2120941398971318410"},{"id":"jpbfn2g31iz5iovg126icbq7l","title":"Gemini Hydrogen 加速交互原型迭代","summary":"日常原型设计与迭代。\n\n在探索和测试想法时，Hydrogen 能用更少的提示词生成干净、可用的布局，让交互项目的快速原型设计与优化变得轻松。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:05:54.000Z","url":"https://x.com/GeminiApp/status/2120941167584108776"},{"id":"rtug94ind3nuemcslhudu9ver","title":"Gemini 推出 Hydrogen 逐步拆解任务并调用应用完成待办","summary":"Google Gemini 官方宣布 Hydrogen 功能，将用户目标逐步拆解，从上传内容、Gmail、Google Drive 及 Airtable、Dropbox 等 Connected Apps 拉取相关上下文。在 Gemini 中开始任务时，它会更频繁调用合适的工具和技能，帮助更快完成待办清单。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:05:31.000Z","url":"https://x.com/GeminiApp/status/2120941072050471156"},{"id":"rt584cexu9fp97te4mb91obzr","title":"Google 发布 Gemini 4 Hydrogen","summary":"Google 发布 Gemini 4 Hydrogen，定位能力强且快速，让 Gemini 4 覆盖更多用户。该模型向 Google AI Studio、Gemini API、Gemini for business、Gemini 应用、Google Search 全量开放，付费 Google AI Pro + Ultra 订阅者可在 Google Antigravity 中使用。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-12T18:05:02.000Z","url":"https://x.com/OfficialLoganK/status/2120940951292268640"},{"id":"rl7315tdvcb3agm4jz3u99e36","title":"Gemini Hydrogen 写作研究助手","summary":"开箱即用的写作、研究和日常工作。\n\nHydrogen 严格遵循你的语气、格式和具体规则，因此邮件草稿、学习指南、改写内容和复杂文档第一次就能直接使用。当你比较产品或综合密集材料时，它能整理出清晰的表格和可视化拆解，同时不遗漏关键细节。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:04:53.000Z","url":"https://x.com/GeminiApp/status/2120940914843795865"},{"id":"hd9c1p8riw1bpzs4yepq4h64d","title":"Hydrogen 用自然语言秒生成可交互代码","summary":"除了知识工作，Hydrogen 还将同样的速度和一次通过准确率带入实时编程，在数秒内把自然语言转化为可运行、可交互的代码。\n\n在 Geminisland 中可以看到它的实际表现——这是一个演示游戏，用户可以通过提示词，借助 Gemini API 上的 Hydrogen 实时在共享岛屿上构建新的 3D 体素结构。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-12T18:03:59.000Z","url":"https://x.com/GoogleAI/status/2120940684924403798"},{"id":"yg1hh9kmy0cj86m7f96b93pqn","title":"Google 发布 Gemini 4 Hydrogen，面向消费者和开发者全面开放","summary":"Google AI 宣布 Gemini 4 Hydrogen 从即日起可用。消费者可在 Gemini App 和 Google Search 中向所有用户开放，Google Sheets 中的 Gemini 面向 Google AI Pro 和 Ultra 订阅者；开发者和企业可通过 Google AI Studio 和 Android Studio 中的 Gemini API 构建，Google Antigravity 及 Gemini for business 面向付费 Pro 和 Ultra 订阅者。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-12T18:03:59.000Z","url":"https://x.com/GoogleAI/status/2120940686811750596"},{"id":"oyvn2ybcdov39n3frh8j060lg","title":"Google 发布 Gemini 4 Hydrogen，扩展 Gemini 4 模型系列","summary":"Google AI 宣布推出 Gemini 4 模型系列新成员 Gemini 4 Hydrogen，面向日常编码和智能体工作流，主打速度与效率。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-12T18:03:58.000Z","url":"https://x.com/GoogleAI/status/2120940683233984862"},{"id":"xron978vcvj09ct0oz6iuvbrj","title":"Google 发布 Gemini 4 Hydrogen，主打日常快速帮助","summary":"Google 官方宣布 Gemini 4 Hydrogen 发布，面向所有人提供前沿智能和快速日常帮助。官方称它更能贴近用户指令行事、正确调用合适的工具，用更少的来回沟通获得可靠输出。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:03:39.000Z","url":"https://x.com/GeminiApp/status/2120940601319260164"},{"id":"v26fsdyhbktgyuedmrx25p58y","title":"Google Gemini 开放推送，覆盖开发者、企业与普通用户渠道","summary":"Google DeepMind 宣布开始向各渠道推送：开发者可在 Google AI Studio、Android Studio 中用 Gemini API，付费 Google AI Pro 和 Ultra 订阅者可在 Google Antigravity 中使用；企业可通过 Gemini for business 和 Google Antigravity 部署；所有用户可在 Google Search 和 Gemini 应用模型下拉菜单中访问。详情见 https://goo.gle/4zDCs8N。","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-12T18:02:37.000Z","url":"https://x.com/GoogleDeepMind/status/2120940342505566438"},{"id":"ckdk8km29wmrflsa2fte7y832","title":"Google 发布 Gemini 4 Hydrogen，任务速度较 3.8 Flash 快 2.5 倍","summary":"Google 在 Carbon + Argon 之后发布 Gemini 4 Hydrogen，主打面向日常任务、编码和智能体工作流的速度与效率。相比 3.8 Flash 任务完成速度快 2.5 倍，并提供 4 档思考级别，用户只需为任务所需的推理深度等待和付费。模型今日起向 Google AI Studio 各档位、Gemini API、Gemini App、Search 以及 Google AI Pro 和 Ultra 订阅用户的 Google Antigravity 推出。","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-12T18:02:12.000Z","url":"https://x.com/sundarpichai/status/2120940236805169182"},{"id":"uy1ayrrlqx1snqsv4lub7whsa","title":"Google DeepMind 发布 Gemini 4 Hydrogen","summary":"Google DeepMind 发布 Gemini 4 Hydrogen，定位快速执行日常编码与智能体工作流，面向 Gemini API、AI Studio、Gemini 应用、Google Search 等全层级开放。","sourceName":"Google DeepMind：Blog（RSS）","firstParty":true,"publishedAt":"2026-11-12T18:00:50.000Z","url":"https://deepmind.google/blog/introducing-gemini-4-hydrogen/"},{"id":"v98atslrmng6mh1ez8840nx38","title":"Google Search 全面接入 Gemini 4 Hydrogen","summary":"Google 宣布 Gemini 4 Hydrogen 已向全球所有用户开放于 Google Search，称为 Search 迄今最大的模型升级。改进包括更细腻的意图理解与指令跟随、增强的 query fan-out 推理以覆盖更多相关子主题链接、更多图片、结构化回复和对比表等可视化响应，以及所有支持 AI Mode 语言下更细致的回答质量。","sourceName":"Google Blog：AI（RSS）","firstParty":true,"publishedAt":"2026-11-12T18:00:00.000Z","url":"https://blog.google/products-and-platforms/products/search/gemini-4-hydrogen-search-upgrade/"},{"id":"e1tuwzogxnhwavo3muu1ivhdy","title":"Gemini 4 Hydrogen (gemini-4-hydrogen) 正式可用并成为 Antigravity 智能体默认模型","summary":"Google 在 Gemini API 更新日志中宣布 Gemini 4 Hydrogen (gemini-4-hydrogen) 正式可用 (GA)，面向日常编码和智能体工作流提供速度与效率。","sourceName":"Gemini API：更新日志（网页）","firstParty":true,"publishedAt":"2026-11-12T00:00:00.000Z","url":"https://ai.google.dev/gemini-api/docs/changelog#11-12-2026"},{"id":"d45gkw7az0yba8svolkwbyw8a","title":"Google 发布 Gemini 4 Hydrogen，主打快速执行与多模型协作","summary":"Google 发布 Gemini 4 Hydrogen，定位为面向日常编码与智能体工作流的快速执行模型，与主打深度推理的 Gemini 4 Carbon 和 Argon 互补，现已覆盖 AI Studio、Gemini API、Gemini 应用、Google Search 等全部层级。","sourceName":"Hacker News：AI 热帖","firstParty":false,"publishedAt":"2026-11-11T16:00:00.000Z","url":"https://blog.google/innovation-and-ai/models-and-research/gemini-models/introducing-gemini-4-hydrogen/"}]},"8febc4b1-e8fa-4418-97c6-eb03dfa73f42":{"publicId":"8febc4b1-e8fa-4418-97c6-eb03dfa73f42","title":"Google发布Gemini Decision 1决策模型与Decisions API","status":"active","sourceCount":14,"reportCount":19,"firstReportAt":"2026-11-11T00:00:00.000Z","latestAt":"2026-11-12T00:55:39.970Z","latest":"谷歌推出 Gemini Decisions API，基于 Gemini Decision 1 模型实现快速多模态决策","digest":"Google 发布 Gemini Decision 1 模型及配套 Decisions API，不再逐 token 生成文本，而是对文本、图像、音频、视频和 PDF 输入一次性回答是非题、选择题和 rubric 评分，单次最多 1,000 个问题、256K 上下文，端到端延迟 150–250 毫秒，每个答案附置信度分数。该 API 已在 Google AI Studio 上线，输入定价 $0.10/百万 token、输出不收费，并提供免费额度供原型开发；Google 称其在共享基准套件上比使用 Interactions API 的 Gemini 3.5 Flash-Lite 成本效率高近 5 倍。\n\n第三方评测给出不同图景：Artificial Analysis 称 Gemini Decision 1 在 Decision Index v2.1 得 66 分，与 Elephant 9B、Jev 1.14 相当，落后并列领先的 Drex Max v1.1 和 GLiDE v1.2 各 7 分。Google 自己展示的演示则称其 4.5 秒扫描 100 张配送照片、每张回答 16 个问题，速度接近 Gemini 3.5 Flash-Lite 的 4 倍。\n\n该模型发布首日即上线 OpenRouter，Google Cloud 上的支持标注为即将推出；开发者使用 Gemini Developer API（v1beta）需 google-genai SDK 3.2 或更高版本。","digestUpdatedAt":"2026-11-12T19:23:03.700Z","reports":[{"id":"shb2cxiblvq7iuzx5ug97p4vi","title":"Latent Space AINews：Google 发布 Gemini Decision 1 决策模型，Claude Fable 5.2 登顶 Agent Arena","summary":"Latent Space 发布 AI 要闻汇总，核心是 Google 抢先 Anthropic 推出生产级校准多模态决策模型 Gemini Decision 1，单次前向完成封闭集决策，支持每请求最多 1000 个问题、256K 上下文，输入 $0.10/1M tokens 且输出免费，端到端延迟约 150–250ms。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-12T05:26:54.000Z","url":"https://latent.space/p/ainews-d-day-decision-models-day/"},{"id":"augt3chxot6cst3txu3h6snl1","title":"谷歌推出 Gemini Decisions API，基于 Gemini Decision 1 模型实现快速多模态决策","summary":"谷歌宣布推出 Gemini Decisions API，由全新 Gemini Decision 1 模型驱动，可在一次快速处理中对文本、图像、视频和 PDF 内容进行至多 1000 项是非判断、选项选择和标准评估。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T00:55:39.970Z","url":"https://www.ithome.com/1/025/858.htm"},{"id":"cwu3md9iafkda12s81kwsz9t7","title":"Google 发布 Gemini Decision 1 决策模型 API，Simon Willison 实测对比","summary":"Google 发布 Gemini Decision 1 决策模型 API，与 Jev 和 OpenAI 同属决策模型类别，支持 yes/no、选择和 rubric 打分三类问题，沿用 Jev 的术语 Noul 表示 yes/no 问题。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-11T22:03:25.000Z","url":"https://simonwillison.net/2026/Nov/11/gemini-decisions-api/"},{"id":"i529ddohm7bqm204xi2fdv7p6","title":"Google 发布 Gemini Decisions API 与 Gemini Decision 1，输入定价 $0.10/M tokens","summary":"Google 发布 Gemini Decisions API，由新模型 Gemini Decision 1 驱动，单次请求可对最多 1000 个问题打分并返回校准概率，输出 token 计费为 0，输入定价 $0.10/M tokens，上下文 262,144 tokens，端到端延迟 150-250 ms。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-11T21:21:42.000Z","url":"https://www.marktechpost.com/2026/11/11/google-gemini-decisions-api-gemini-decision-1/"},{"id":"e055uwm3p70cmgp80bpk1wn79","title":"Google 发布 Gemini Decision 1 决策模型，Gemini API 每百万输入 token 仅 $0.10","summary":"Google 在 Gemini API 推出新决策模型 Gemini Decision 1，价格 $0.10 per 1M input tokens 且无额外费用，原生支持图像、音频、视频和 PDF，256K 上下文窗口，可回答 1K questions，可在 API 免费试用。Google Labs VP Josh Woodward 转发并表示团队经常用它构建应用，称其让应用更快更智能；附图基准对比显示其在 JeeBench 92.2%、MMAU 71.8% 等项领先对比模型。","sourceName":"X：Josh Woodward (@joshwoodward, Google Labs VP)","firstParty":false,"publishedAt":"2026-11-11T21:01:30.000Z","url":"https://x.com/joshwoodward/status/2120622974277734716"},{"id":"tc20zb2magcy73drkedizwofu","title":"Google DeepMind 发布 Gemini Decision 1，单次可处理 1,000 个封闭式问题","summary":"Google DeepMind 推出 Gemini Decisions API，底层模型 Gemini Decision 1 面向是非题、选择题和量表评分等封闭式决策，单次可处理最多 1,000 个独立问题，支持文本、图像、音频、视频和 PDF，150 到 250 毫秒内返回概率与置信度。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-11T20:12:46.000Z","url":"https://the-decoder.com/google-joins-the-decision-model-wave-with-gemini-decision-1-scoring-1000-questions-in-a-single-pass/"},{"id":"ac59bdk8ftgxgvflbfwfsshpe","title":"Gemini Decision 1 用清单式提问做照片决策","summary":"Gemini Decision 1 把照片判断改成回答 yes/no、多选和评分清单，而非让模型自由描述图片。演示中它 4.5 秒扫描 100 张配送照片，每张同时回答 16 个问题，速度接近 Gemini 3.5 Flash-Lite 的 4 倍，并据评分将异常件路由到理赔审核。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-11T18:26:32.000Z","url":"https://x.com/Google/status/2120583972505760016"},{"id":"ai5qd8q6pvshexpvj80op6hzm","title":"Google 推出 Decisions API 快速决策","summary":"大多数模型是为生成文本、创意内容或逐步推理而构建的。但并非每项任务都需要书面答案。\n\n当工作流或智能体只需要快速做出判断时，Decisions API 会返回经过校准的置信度分数（端到端 150–250 毫秒），价格为每 100 万输入 token 0.10 美元，在共享基准测试套件上，其成本效率比使用 Interactions API 的 Gemini 3.5 Flash-Lite 高出近 5 倍。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-11T18:26:31.000Z","url":"https://x.com/Google/status/2120583968676577709"},{"id":"mj3riahx31kxc8bg1qk1mx3lh","title":"Google 发布 Gemini Decision 1 模型及 Gemini Decisions API","summary":"Google 在 Google AI Studio 推出 Gemini Decisions API，由新模型 Gemini Decision 1 驱动。该模型不再逐 token 生成文本，而是将文本、图像、音频、视频和 PDF 输入与最多 1,000 个问题对照，单次通过即给出决策，不按输出 token 计费。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-11T18:26:30.000Z","url":"https://x.com/Google/status/2120583966272983331"},{"id":"hh33gzk6lm10h6i2kt66g9lbx","title":"Google 首个决策模型 Gemini Decision 1 上线 OpenRouter","summary":"Google 首个决策模型 Gemini Decision 1 上线 OpenRouter，发布首日即可调用。该模型可接收文本、图像、音频、视频或 PDF 加类型化问题，以概率形式回答是/否问题、从最多 255 个选项中选择或打分，上下文 262K，定价 $0.10/M input、output 免费。","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-11T18:23:00.000Z","url":"https://x.com/OpenRouter/status/2120583084005605816"},{"id":"wlkx8ntz14q1azrcsx0u3npmj","title":"Artificial Analysis 评测 Google 首个决策模型 Gemini Decision 1，Decision Index 得 66 分","summary":"Artificial Analysis 评测 Google DeepMind 发布的首个决策模型 Gemini Decision 1，在 Artificial Analysis Decision Index v2.1 得 66 分。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-11T18:18:53.000Z","url":"https://x.com/ArtificialAnlys/status/2120582049522127205"},{"id":"wksvftoklhf028l767f8xucrj","title":"Google AI Studio 决策 API 文档","summary":"查看 API 文档，了解更多入门信息！https://aistudio.google.com/docs/decisions-api","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-11T18:16:51.000Z","url":"https://x.com/OfficialLoganK/status/2120581534600343641"},{"id":"n79t0spfz7zgwe7qcvxvwaauv","title":"Google 在 Gemini API 推出 Gemini Decision 1 决策模型","summary":"Google 推出 Gemini Decision 1，定位为 frontier decision 模型，已在 Gemini API 开放。定价为每 100 万输入 token $0.10 且无额外费用，原生支持图像、音频、视频和 PDF，提供 256K 上下文窗口与 1K questions，可在 API 中免费试用。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-11T18:16:26.000Z","url":"https://x.com/OfficialLoganK/status/2120581433639198885"},{"id":"k1o7m8sfd4polrbxmonxud4vd","title":"Google DeepMind 发布 Gemini Decision 1 模型与 Decisions API","summary":"Philipp Schmid 宣布 Gemini Decision 在 Google DeepMind 内部原型孵化 6 周后，正式随新 API 一起发布 Gemini Decision 1 模型。作者本人参与了 API 与模型的设计、构建和评估，并提供文档、博客和 Playground 入口供试用。","sourceName":"X：Philipp Schmid（Google DeepMind 开发者体验） (@_philschmid)","firstParty":false,"publishedAt":"2026-11-11T18:15:43.000Z","url":"https://x.com/_philschmid/status/2120581250582995318"},{"id":"yhy98p14wmm973u361pelzt3e","title":"Google DeepMind 发布 Gemini Decisions API 及 Gemini Decision 1 模型","summary":"Google DeepMind 的 Philipp Schmid 发布 Gemini Decisions API，用于回答是非题、选择题和 rubric 问题，由新模型 Gemini Decision 1 驱动。该 API 支持文本、图像、音频、视频和 PDF 输入，单次请求最多 1,000 个问题，256k 上下文，端到端延迟 150-250 ms，输入价格 $0.10 per 1M tokens、输出免费，每个答案附带置信度分数。","sourceName":"X：Philipp Schmid（Google DeepMind 开发者体验） (@_philschmid)","firstParty":false,"publishedAt":"2026-11-11T18:15:42.000Z","url":"https://x.com/_philschmid/status/2120581248859201675"},{"id":"a0qorvsg9mk2771bmeq28zxbz","title":"Gemini 决策 API 上线","summary":"在此了解更多 https://blog.google/innovation-and-ai/technology/developers-tools/gemini-decisions-api","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-11T18:15:20.000Z","url":"https://x.com/sundarpichai/status/2120581156882285031"},{"id":"rlhz0uwxo2p8xhc7vnbaoko7i","title":"Google 发布 Gemini Decisions API 与 Gemini Decision 1 决策模型","summary":"Sundar Pichai 宣布在 Google AI Studio 推出 Gemini Decisions API，由新模型 Gemini Decision 1 驱动，面向封闭集选择而非逐 token 生成文本。","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-11T18:15:20.000Z","url":"https://x.com/sundarpichai/status/2120581155078729728"},{"id":"r8hsm3m3munjwk1n3u885zszw","title":"Google 发布 Gemini Decisions API 与 Gemini Decision 1 模型，专注快速多模态封闭式决策","summary":"Google 推出 Gemini Decisions API，由新模型 Gemini Decision 1 驱动，可在 150-250ms 端到端延迟内对文本、图像、音频、视频和 PDF（最多 256K tokens）一次性评估最多 1000 个是/否、多选和评分题。","sourceName":"Google Blog：AI（RSS）","firstParty":true,"publishedAt":"2026-11-11T18:00:00.000Z","url":"https://blog.google/innovation-and-ai/technology/developers-tools/gemini-decisions-api/"},{"id":"xyi59vw1zcxyc6o44nlsy2eey","title":"Google 发布 Gemini Decision 1 模型及 Decisions API","summary":"Google 在 Gemini API 更新日志中发布 Gemini Decision 1（gemini-decision-1）和 Decisions API，用于对文本、图像、音频、视频和 PDF 做快速、校准的二元、分类和 rubric 决策，输出零 token。官方同步提供了定价、速率限制和 Decisions API 入门指南。","sourceName":"Gemini API：更新日志（网页）","firstParty":true,"publishedAt":"2026-11-11T00:00:00.000Z","url":"https://ai.google.dev/gemini-api/docs/changelog#11-11-2026"}]},"82c796c0-3bf1-4c3a-8368-56913b4bf85d":{"publicId":"82c796c0-3bf1-4c3a-8368-56913b4bf85d","title":"Anthropic启动IPO路演，估值预期回落至1.25–1.75万亿美元","status":"active","sourceCount":21,"reportCount":78,"firstReportAt":"2026-10-25T16:00:00.000Z","latestAt":"2026-11-12T11:30:46.000Z","latest":"Anthropic 官宣首次公开募股（IPO）","digest":"Anthropic 已启动 IPO 路演，拟发行 8.25 亿股 A 类普通股，其中公司发售约 8.01 亿股、现有股东出售约 2365 万股，公司不获后者所得；发行价区间为每股 70–78 美元，拟在纳斯达克以代码 ANT 上市。据路透社公布的招股说明书草案，公司计划通过 IPO 筹集最多 644 亿美元，并向谷歌、英伟达和 AMD 等基石投资者私募融资 260 亿美元，计入博通、美光、微软和台积电等出资后募资规模最高可达 904 亿美元。\n\n据《金融时报》援引投资者消息，公司拟募资 800–1000 亿美元，目标估值 1.25 万亿–1.75 万亿美元，CEO 阿莫迪已接受低于此前预期的估值；公司 9 月曾瞄准最高 2 万亿美元。据 WSJ，公司本周将设定估值区间，计划下周四或周五挂牌，部分机构投资者仍希望估值低于上周讨论的 1.5 万亿美元。\n\n估值下调发生在投资者质疑之后。据 Reuters 和 WSJ，投资者认为 1.5 万亿美元过高，有人提出仅 1 万亿美元，并怀疑原定下周启动的路演能否如期进行，还在等待更新文件未包含的 10 月营收数据。更新后的 S-1/A 首次披露第三季度业绩：经营利润从二季度盈利 9.74 亿美元转为亏损 5.67 亿美元，Q3 营收 170 亿美元，算力成本占营收比例从 48% 升至 58%；算力与基础设施合同承诺约 8954 亿美元，另有最高 1750 亿美元尚未定价。上市后，长期受益信托可任命七名董事中的四席，七位联合创始人合计掌握 50.1% 投票权。","digestUpdatedAt":"2026-11-12T12:02:17.495Z","reports":[{"id":"k99zjo9hbtous9r6vmmz7pxyh","title":"Anthropic 官宣首次公开募股（IPO）","summary":"Anthropic 官方宣布启动首次公开募股（IPO），并公布入口 ipo.anthropic.com。Anthropic 已向 SEC 提交注册声明及招股说明书，证券在注册声明生效前不得出售，初步招股说明书可经高盛与摩根士丹利获取。","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-12T11:30:46.000Z","url":"https://x.com/AnthropicAI/status/2120841731302154708"},{"id":"xi0y19pbadxpvgcmzsm7c5byg","title":"Anthropic IPO 路演视频披露多芯片策略与算力乘数细节","summary":"Simon Willison 整理了 Anthropic IPO 路演视频的转录稿，称其中包含此前未公开的业务信息。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-11T15:11:59.000Z","url":"https://simonwillison.net/2026/Nov/11/anthropic-ipo-roadshow/"},{"id":"r5kn7uexy6jx97qwxwvnpqrom","title":"Anthropic IPO 拟募资最高 90.4B 美元，或成史上最大上市","summary":"Bloomberg 报道 Anthropic IPO 已获数倍于发行份额的订单，主要来自大型机构投资者的锚定级意向。公司通过 IPO 加私募配售寻求最高 $90.4B，将超过 SpaceX 的 $85.7B 纪录成为史上最大上市，完全稀释估值目标约 $1.4T；Goldman Sachs 和 Morgan Stanley 牵头共 22 家银行，股票将以 ANT 在纳斯达克全球精选市场交易。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T14:38:51.000Z","url":"https://x.com/rohanpaul_ai/status/2120526677247939001"},{"id":"ajjv9abs8vd20j05emcig98ai","title":"WSJ：Anthropic 7 位创始人 IPO 各套现约 2.5 亿美元并保留控制权","summary":"WSJ 报道，Anthropic 7 位创始人将在 IPO 中各出售约 2.5 亿美元股票，每人保留约 180 亿美元持仓。据公司文件，每人出售近 3.4M 股，发行价区间预计 70 至 78 美元，上市预计下周进行，估值接近 1.3 万亿美元，募资 800 亿美元以上，部分通过包括 Google 在内的私募配售。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T05:47:04.000Z","url":"https://x.com/rohanpaul_ai/status/2120392847505715324"},{"id":"m7ul4psbkb5zyp0t254fr986o","title":"Anthropic 投资需求火热，承销商拟将 IPO 目标估值上调回 $1.5T 或更高","summary":"FT 报道，因投资者需求旺盛，Anthropic 承销商计划上调 IPO 定价，把目标估值拉回 $1.5T 或更高。周二文件设定 $70-$78 的发行区间，计入员工期权和受限股后对应 $1.26T-$1.41T 估值；若定价超出区间，募资将超过 $100B，其中 Google、Nvidia 和 Microsoft 将按 IPO 价格投资 $26B。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T00:58:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120320127484969162"},{"id":"eo7ozgw5sry6i4d0al4cu43py","title":"Anthropic S-1 披露七位创始人 IPO 各套现约 2.5 亿美元","summary":"Anthropic 的 S-1 文件显示，七位联合创始人每人将出售 3,378,378 股，按 70 至 78 美元的发行价区间，每人套现约 2.36 亿至 2.64 亿美元。IPO 估值可能达到 1.4 万亿美元，七人通过 Class F 超级投票权股份合计控制 51.1% 的投票权。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T19:57:52.000Z","url":"https://techcrunch.com/2026/11/10/all-7-anthropic-founders-will-each-cash-out-about-250m-in-ipo/"},{"id":"j8x08g5wo30akk4mast68n79d","title":"Anthropic 再次修订 S-1：宣布已达责任扩展政策能力阈值，IPO 定价 $70-$78","summary":"Anthropic 再次修订 IPO 申请文件 S-1（Amendment No. 2），宣布已越过其 Responsible Scaling Policy 设定的阈值，即 AI 正大幅加快 AI 研究速度、需更强安全检查。这一判断基于其对未来模型的预期而非现有模型的表现，一周前的文件还只说\"可能即将\"越过。文件同时将 IPO 发行价定为每股 $70 至 $78。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T19:04:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120231037569790385"},{"id":"go546q78uprsfowd1zsj1ig2d","title":"Anthropic 启动 IPO 路演：拟以每股 70 至 78 美元发行，估值最高约 1.4 万亿美元","summary":"据 Bloomberg 报道，Anthropic 启动 IPO 路演，拟发行最多 8.25 亿股 Class A 普通股，定价 70 至 78 美元，估值最高约 1.4 万亿美元，股票将以代码 ANT 在纳斯达克上市，最快下周四或周五开始交易。按区间上限募资约 644 亿美元，其中约 625 亿美元来自 Anthropic 自身的 8.01351 亿股新股，现有股东仅出售 2364.8646 万股，所得几乎全部归公司；此前传闻估值曾高达 2 万亿美元，下调发生在科技股抛售与选民对 AI 数据中心态度转冷的背景下。作者补充引用文件称，Anthropic 代码库 90% 以上的贡献由 Claude 编写。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T18:45:31.000Z","url":"https://x.com/rohanpaul_ai/status/2120226361864536385"},{"id":"qd2nhcf09xkrsuynw5ss7yzt7","title":"Anthropic 启动 IPO 路演，定价最高 78 美元、估值至多 1.4 万亿美元","summary":"Anthropic 启动 IPO 路演，拟以每股 70 至 78 美元发行最多 8.25 亿股 Class A 普通股，估值最高约 1.4 万亿美元，股票代码 ANT，最快下周四或周五在 Nasdaq 开始交易。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T18:40:01.000Z","url":"https://x.com/rohanpaul_ai/status/2120224979098939403"},{"id":"yshr81morbvxs39fq2y2rw6rg","title":"Gary Marcus 质疑 Anthropic 1.4 万亿美元 IPO 估值","summary":"Gary Marcus 评论 Anthropic 拟以最高 1.4 万亿美元估值 IPO，称该公司除一个异常季度外从未盈利，未来负债接近 9000 亿美元。他引用 Q2 环比增长 147% 而 Q3 降至 47% 的数据，认为 tokenmaxxing 退潮与中国竞品崛起使万亿估值失去依据，并援引 S-1 中公司自认成本将上升、收入增速难以为继的表述。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:37:21.000Z","url":"https://garymarcus.substack.com/p/just-say-no-to-anthropics-ipo"},{"id":"vsl8mxe1wtsjxzuon4g65ap8b","title":"Anthropic IPO 定价每股 $70.00 至 $78.00，估值最高可达 $1.4 万亿","summary":"Anthropic 周二确认其 IPO 发行价预计在 $70.00 至 $78.00 每股之间，估值最高 $1.4 万亿，低于此前预期的最高 $2 万亿。据 The Wall Street Journal 报道，股票目标在下周四或周五开始交易，将申请在纳斯达克以代码 \"ANT\" 上市其 A 类普通股；作为对比，OpenAI 上周估值为 $1.25 万亿。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:06:54.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030703/anthropic-ipo-1-4-trillion"},{"id":"bbqkapwzzux4qt6ns0zsh7b7s","title":"Anthropic 将 IPO 发行价区间定为 70 至 78 美元，隐含估值达 1.404 万亿美元","summary":"Anthropic 在更新后的 IPO 招股文件中将发行价区间定为每股 70 至 78 美元，共发行 8.25 亿股 A 类股，预计募资 577.5 亿至 643.5 亿美元，若按区间上限定价隐含估值可达 1.404 万亿美元，高于其 5 月融资时的 9650 亿美元估值。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:01:39.000Z","url":"https://techcrunch.com/2026/11/10/anthropic-sets-ipo-price-range-of-70-to-78-per-share-to-reach-an-implied-valuation-of-1-404-trillion/"},{"id":"m5rcmn2em2b1mrik078lupej8","title":"Anthropic 启动 IPO 路演：发行价 70 至 78 美元，目标估值超 1 万亿美元","summary":"Anthropic 启动 IPO 路演，公开发行 8.25 亿股 A 类普通股，定价每股 70 至 78 美元，目标估值最高 1.02 万亿美元，股票将在纳斯达克以代码 ANT 交易。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-10T12:13:03.000Z","url":"https://the-decoder.com/anthropic-kicks-off-ipo-roadshow-offering-shares-at-70-to-78-and-targeting-a-trillion-dollar-valuation/"},{"id":"hq4udij8d72th4omv72z1skgj","title":"Anthropic 拟通过 IPO 筹集最多 644 亿美元，另向谷歌、英伟达等私募融资 260 亿美元","summary":"据路透社公布的招股说明书草案，Anthropic 计划通过 IPO 筹集最多 644 亿美元，并向谷歌、英伟达和 AMD 等基石投资者私募融资 260 亿美元，计入博通、美光、微软和台积电等出资后募资规模最高可达 904 亿美元。IPO 初步定价区间为每股 70 至 78 美元，此前一日 Anthropic 曾撤回拟筹资 693 亿美元的备案文件并称定价细节不准确。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T11:40:20.710Z","url":"https://www.ithome.com/1/025/127.htm"},{"id":"d4f8o2c9r7r8b7fsdqnpev3eu","title":"据报道 Anthropic 推进 IPO，计划下周四或周五挂牌","summary":"据 The Wall Street Journal 报道，Anthropic 将在本周设定估值区间，计划下周四或周五开始交易。部分机构投资者正推动估值低于上周讨论的 1.5 万亿美元目标，该数字已低于几个月前传闻的 2 万亿美元。报道还提到其主要竞争对手 OpenAI 上周融资 110 亿美元后估值约为 1.25 万亿美元，低于其最初寻求的 200 亿美元融资规模。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T01:27:12.000Z","url":"https://techcrunch.com/2026/11/09/anthropic-reportedly-plans-to-move-forward-with-ipo-plans/"},{"id":"wrxlh5gesmj36fresoxbriak2","title":"Anthropic 启动 IPO 路演，拟发行 8.25 亿股 A 类普通股并申请以代码 ANT 上市纳斯达克","summary":"Anthropic 启动拟议 IPO 路演，拟发行 825,000,000 股 A 类普通股，其中 801,351,354 股由 Anthropic 发售、23,648,646 股由部分现有股东出售，Anthropic 不获后者出售所得款项。","sourceName":"Anthropic：Newsroom（网页）","firstParty":true,"publishedAt":"2026-11-09T16:00:00.000Z","url":"https://www.anthropic.com/news/roadshow-launch"},{"id":"n0tybsrqj4ylarv5v5ilu4pj5","title":"Bloomberg 报道 AI 融资遇冷，Anthropic IPO 估值讨论下探至 1.1 万亿美元","summary":"Bloomberg 报道，亚洲杠杆 AI 头寸遭遇追缴保证金，券商警告抛售可能延续，估值在交易完成前或进一步下跌。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T12:22:01.000Z","url":"https://x.com/rohanpaul_ai/status/2119767465253331109"},{"id":"cjulee90gasnt7mbhmxcuiiqj","title":"消息称 Anthropic 仍推进 IPO：拟募资 800 亿至 1000 亿美元，估值预期回落","summary":"据《金融时报》报道，Anthropic 仍在推进感恩节前的 IPO，预计募资 800 亿至 1000 亿美元，目标估值 1.25 万亿至 1.75 万亿美元，CEO 阿莫迪接受估值低于此前投资者预期的水平。科技股抛售和美国中期选举结果使上市难度上升，OpenAI 也已将私募估值从 1.4 万亿美元下调至 1.25 万亿美元。七位联合创始人已承诺将个人所持股权的 80% 捐给慈善事业。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-08T00:44:04.537Z","url":"https://www.ithome.com/1/023/854.htm"},{"id":"okhx4jjwucd647299qwzsl6ua","title":"Anthropic 拟感恩节前 IPO，接受低于预期的估值，募资 800–1000 亿美元","summary":"据《金融时报》援引投资者的消息，Anthropic 计划在感恩节前 IPO，拟募资 800–1000 亿美元，估值 1.25–1.75 万亿美元，低于最乐观投资者期望的 2 万亿美元，但高于当前 9650 亿美元。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-07T17:37:25.000Z","url":"https://the-decoder.com/anthropic-pushes-ahead-with-pre-thanksgiving-ipo-despite-tech-selloff-accepts-lower-valuation/"},{"id":"losfqwxesuanjnt62v032oo9o","title":"Anthropic IPO 估值存分歧，1.5 万亿美元仍被部分投资者嫌贵","summary":"据路透社报道，Anthropic 冲刺史上最大 IPO 时估值预期持续下调，原拟寻求高达 2 万亿美元估值，部分机构投资者认为 11 月上市时应在 1.5 万亿至 1.6 万亿美元之间，甚至有大型投资者认为更接近 1 万亿美元。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-07T01:36:48.637Z","url":"https://www.ithome.com/1/023/640.htm"},{"id":"kv9zqeiqr9wj29j6vmq9q6je6","title":"WSJ：投资者将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T","summary":"据 WSJ，投资者已将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T，部分人认为 $1T 更现实。民主党中期选举获胜后数据中心禁令担忧引发 $3.2T 美股抛售；Anthropic 10 月底 run rate 仍超 $80B，9 月 30 日持有 $146.6B 现金。OpenAI 在 $1.25T 估值下仅募得 $30B 目标中的 $11B，同样反映融资走弱。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-06T14:56:34.000Z","url":"https://x.com/rohanpaul_ai/status/2118719195072659833"},{"id":"ia9wi0z09zfes5ewdf4agb6nf","title":"Anthropic 1.5 万亿美元 IPO 因投资者质疑估值遇阻","summary":"据 Reuters，Anthropic 的 IPO 遇阻，投资者质疑 1.5 万亿美元估值过高，有投资者提出仅 1 万亿美元，公司 9 月曾瞄准最高 2 万亿美元估值。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-06T11:38:17.000Z","url":"https://the-decoder.com/anthropics-1-5-trillion-ipo-hits-resistance-as-investors-balk-at-valuation/"},{"id":"zzv4fx8jpa3068v4y2wxsw2ey","title":"Newcomer：OpenAI 与 Anthropic 融资路径分化，Anthropic IPO 仍在推进","summary":"Newcomer 作者采访参与两家融资的投资人后写道，Anthropic 正与 OpenAI 拉开距离，而 OpenAI 渴望翻身故事。有投资人称共同基金等长期投资者对 Anthropic 股份需求无限，预计 IPO 将在感恩节前完成；民主党中期选举大胜后政治环境更严峻，但 Anthropic 与民主党关系相对友好。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-04T21:15:13.000Z","url":"https://www.newcomer.co/p/latest-fundraising-efforts-show-openai"},{"id":"mr034xi1abyzx7gazv7l248lg","title":"Anthropic 明年 700 亿美元算力账单超全年收入，S-1 细节遭播客拆解","summary":"Saito 在听完 Prof G Markets 播客后撰文分析 Anthropic S-1 修订稿，指出其未来几年算力与数据中心总承诺达 8950 亿美元，其中未来 12 个月到期 700 亿美元，超过其 680 亿美元的年化收入（上季度收入 170 亿美元，同比涨 12 倍但环比增速从 144% 降至 47%）。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-11-04T09:37:20.000Z","url":"https://x.com/SaitoWu/status/2117914080371782063"},{"id":"zv5dl1agqwo6tkmhdamy17lt5","title":"Ed Zitron 解析 OpenAI 1.25 万亿美元估值融资与 Anthropic S-1/A 中的万亿级算力承诺","summary":"Ed Zitron 撰文认为 AI 行业资金正在枯竭。OpenAI 上周以 1.25 万亿美元估值融资 110 亿美元，低于此前计划的 300 亿美元、1.4 万亿美元估值；据 The Information，其 Q1 2026 成本收入与研发支出合计 121 亿美元，截至 3 月底持有逾 730 亿美元现金及有价证券。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:16:20.000Z","url":"https://www.wheresyoured.at/running-dry/"},{"id":"byq9z2oinyhjrd8hrxql51wg5","title":"Anthropic S-1 新披露显示算力成本占比升至 58%，利润率承压","summary":"TechCrunch 分析 Anthropic 更新的 S-1 文件披露，Q3 营收达 170 亿美元、环比增长近 50%，但算力占营收比例从上一季的 48% 升至 58%，每美元算力对应营收从峰值约 2.08x 回落至 1.72x。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:07:01.000Z","url":"https://techcrunch.com/2026/11/03/anthropic-is-still-grappling-with-the-economics-of-compute/"},{"id":"fey67gtp70ulqn8j5il7kycxg","title":"Anthropic 在 S-1/A 招股文件中警示递归自我改进（RSI）临近","summary":"Anthropic 在周一更新的 S-1/A 招股补充文件风险提示中称，公司已利用 AI 开发新模型且部分能力跃升未被及时察觉，基于对下一代模型的内部预期，可能很快触及《负责任扩缩策略》定义的“由 AI 带来的爆发式技术进展”，即递归自我改进（RSI）标准。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-03T08:03:19.683Z","url":"https://www.ithome.com/1/021/626.htm"},{"id":"dertdpzq3sm7jhkbxyfqwxspp","title":"Anthropic 修订版 IPO 文件披露 8954 亿美元算力承诺，总额可达 1.07 万亿美元","summary":"Anthropic 在修订版 IPO 文件中披露 8954 亿美元算力承诺，另有最高 1750 亿美元合同尚未定价，总额约 1.07 万亿美元，约为其前九个月 332 亿美元收入的 32 倍。款项持续到 2045 年，一年内到期 698 亿美元，而公司现金及短期投资为 1319 亿美元；季度环比增速从 144% 放缓至 47%，收入达 170 亿美元，算力成本升至销售额的 58%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-03T00:03:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117407218849157258"},{"id":"h052dra38w9bfsy0ne6frvfpv","title":"GPU 租金半年翻倍，Tomasz Tunguz 解析 2027 年 AI 实验室的久期匹配难题","summary":"Tomasz Tunguz 基于 Anthropic S-1/A 数据分析称，GPU 短租价格从 $3 涨到 $12-13/小时，使 Anthropic 混合 GPU 等效小时成本从 $3.10 升至 $5.65。","sourceName":"Tomasz Tunguz 博客（VC 分析）","firstParty":false,"publishedAt":"2026-11-03T00:00:00.000Z","url":"https://tomtunguz.com/the-financial-engineering-essential-for-ai-in-2027/"},{"id":"p61czu93us1j0lli5em6rjkte","title":"WSJ：大投资者希望 Anthropic IPO 估值定在 1.5 万亿至 1.6 万亿美元","summary":"据 WSJ，大投资者希望 Anthropic 的 IPO 估值定在 1.5 万亿至 1.6 万美元区间，低于数月来讨论的近 2 万亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T23:40:43.000Z","url":"https://x.com/rohanpaul_ai/status/2117401551526600969"},{"id":"uj1dp8gyin78j1xfse943y5w0","title":"Anthropic 在 S-1A 中披露可能很快达到自身 RSI 定义","summary":"TechCrunch 报道，Anthropic 在周一修订的 S-1A 文件风险因素部分新增表述，称内部估计显示其可能很快达到负责任扩展政策中「AI 带来的显著加速进展」的定义，且过去曾未察觉 AI 研发带来的能力跃升，但目前没有任何现有模型被认定越过该阈值。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-02T22:14:50.000Z","url":"https://techcrunch.com/2026/11/02/anthropic-warns-that-its-very-close-to-rsi-capability-aka-self-building-ai/"},{"id":"xiu342i7osbgfxe2ezhrjndl0","title":"Anthropic 算力与基础设施合同承诺达 $895.4B，其中 $447.5B 须在 2031 年前支付","summary":"Anthropic 在更新的 IPO 文件中首次披露第三季度业绩，算力与基础设施合同承诺总额约 $895.4B，其中 $447.5B 须在 2031 年前支付，仅 $213.8B 可取消或附带条件。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T21:28:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117368258571784296"},{"id":"p2ckhch6idwqa3tpmqqp2inb8","title":"Anthropic 更新的 S1/IPO 文件称未来模型可能临近递归自我改进阈值","summary":"Anthropic 更新的 S1/IPO 申报文件显示未来模型可能很快达到其递归自我改进（RSI）阈值，即 AI 能力以无重大 AI 帮助时最快持续速度的 2 倍提升，1 年相当于 2 年进展。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T18:43:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117326734442049563"},{"id":"xvemmg9p83lxqktk7mc47zhcr","title":"Anthropic 更新 IPO 文件首次披露第三季度财报，从盈利 9.74 亿美元转为亏损 5.67 亿美元","summary":"Anthropic 更新 S-1 IPO 文件并首次披露第三季度业绩，经营利润从二季度盈利 9.74 亿美元转为三季度亏损 5.67 亿美元，主因是 50 亿美元的高价短期算力和 20 亿美元员工捐赠配比的非现金支出。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T16:01:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117285920500273582"},{"id":"dpm21l66z2iizblehsdg09c8t","title":"美国白宫科技顾问萨克斯称 Anthropic 可能成为资本主义史上最伟大企业","summary":"美国白宫科学与技术顾问会议主席戴维·萨克斯在 All-In 播客分析 Anthropic 的 S-1 文件，称其很可能成为资本主义历史上最伟大企业，也可能是回报最高的风险投资项目。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T22:56:28.467Z","url":"https://www.ithome.com/1/020/633.htm"},{"id":"yqblvh40gus1ssc0rjvawh6fu","title":"Anthropic IPO 招股文件披露近 9000 亿美元隐性债务","summary":"Anthropic 近日提交 IPO 招股文件，彭博社报道其计划未来在服务器、建筑和电力等领域投入近 9,000 亿美元债务。该公司资产负债表显示 1,175 亿美元负债和 1,120 亿美元现金，而租赁合同及数据中心、电力和 GPU 采购协议等表外义务未直接体现；Anthropic 计划通过增加收入和筹集资金支付这些负债。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T03:25:09.697Z","url":"https://www.ithome.com/1/020/444.htm"},{"id":"vyd3tzicoe478uo8njsr8zt2v","title":"The Verge 解读 Anthropic S-1 文件中的奇迹叙事与风险披露","summary":"The Verge 分析 Anthropic 提交的 335 页 S-1 招股书，其中创始人信以带来奇迹时代为愿景，同时用 94 页风险因素警告模型可能对人类构成灾难性甚至生存风险。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-30T13:11:05.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1023070/anthropic-ipo-risk-factors-filing-miracles"},{"id":"ix29bodadp5bou498z79oflc2","title":"Anthropic S-1 披露：三分之二以上算力用于研发，服务客户仅占约四分之一","summary":"Rohan Paul 引用 Anthropic S-1 指出，至少三分之二的芯片开支用于模型训练、研发和 Claude 内部使用，而非服务客户。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-30T01:28:37.000Z","url":"https://x.com/rohanpaul_ai/status/2115979152100864127"},{"id":"wb6emxuh5ob2wh96egtwawgfu","title":"Anthropic S-1 文件解读：财务表现强劲但增长放缓存隐忧","summary":"作者通读 Anthropic 公开版 S-1 文件，认为公司财务状况好于预期：2026 年第二季度收入从一季度的 47 亿美元增至 116 亿美元，并录得首个运营利润，截至 6 月底现金储备仅次于 Google 和 Berkshire Hathaway。","sourceName":"Timothy B. Lee：Understanding AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T19:10:41.000Z","url":"https://www.understandingai.org/p/anthropics-financials-are-surprisingly"},{"id":"o37r0y04qmlpx7m674ztwgsjr","title":"Anthropic 披露约 250 个客户年消费超 1000 万美元","summary":"Anthropic 在 Form S-1 注册文件中披露，截至 2026 年 9 月 30 日的 12 个月内，约 250 个客户对 Claude 的支出超过 1000 万美元。Fortune 10 全部企业每年支付至少 10 万美元，超过 50% 的 Fortune 500 和超过 30% 的 Global 2000 亦是如此；年付 10 万美元以上的客户贡献 2025 年收入的 76%，低于 2023 年的 90%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-29T17:19:28.000Z","url":"https://x.com/rohanpaul_ai/status/2115856053015580896"},{"id":"r9bmkfh02wkycc8zmhw87h4q9","title":"SemiAnalysis 分析师解读 Anthropic S-1 招股书背后的 AI 经济账","summary":"The Verge Decoder 节目邀请 SemiAnalysis 分析师 Joey Brookhart 解读 Anthropic 提交的 S-1 招股书，公司拟在纳斯达克上市，估值区间 1.5 万亿至 2 万亿美元。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T14:00:00.000Z","url":"https://www.theverge.com/podcast/1021322/anthropic-ipo-filing-s-1-claude-semianalysis-joey-brookhart-interview"},{"id":"iuma7p8unle567lzy6hp5jpw9","title":"The Verge 解读 Anthropic S-1：约 8500 亿美元 compute 承诺押注递归自我改进","summary":"The Verge 作者分析 Anthropic S-1，认为其商业模式依赖高速增长：2026 上半年营收同比增长 14 倍至 $16.3 billion，净收入留存率 900%，但不可撤销采购承诺合计 $265.6 billion，加上未开始的租赁协议 $321.4 billion 及其他协议，未来 20 年承诺至少约 $850 billion。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T13:30:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1021476/anthropic-s-1-compute-recursive"},{"id":"x2h1bp5shee6v508nw7pjtvas","title":"Ed Zitron 长文解析 Anthropic S-1：称其把散户当作退出流动性","summary":"Ed Zitron 撰文批评 Anthropic 的 S-1 招股书，指其仅披露 Q2 盈利数据、省略 Q3 现金状况和付款明细，是在公司基本面变化前误导投资者。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-10-28T17:51:00.000Z","url":"https://www.wheresyoured.at/exit-liquidity/"},{"id":"vidjbhx5bf45wdl488kst1wv8","title":"Anthropic IPO 文件披露现金及短期投资达 131.7B 美元，超过 Amazon 和 Microsoft","summary":"Anthropic 的 IPO 文件显示其现金及短期投资达 $131.7B，超过 Amazon 和 Microsoft，在美国非银行公司中仅次于 Berkshire Hathaway 和 Alphabet。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T17:11:27.000Z","url":"https://x.com/rohanpaul_ai/status/2115491649543635378"},{"id":"x1rs553t7mu2o69tdy90e54nc","title":"TechCrunch 解析 Anthropic IPO 治理结构：公众股东对董事会几乎没有话语权","summary":"TechCrunch 发文分析 Anthropic IPO 后的治理结构，公众股东对董事会人选几乎没有话语权。Long-Term Benefit Trust（成员包括 Ben Bernanke）持有 Class T 股，可选举和罢免 7 个董事席位中的多数；7 位联合创始人合计掌握 50.1% 股东投票权和 3 个董事会席位。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T15:27:21.000Z","url":"https://x.com/rohanpaul_ai/status/2115465450469601487"},{"id":"gxwqce1swocfo9bp3dgqy3dnj","title":"Anthropic S-1 显示 90% 增量毛利，SemiAnalysis 播客详解其中数字","summary":"Saito 转述 SemiAnalysis 播客对 Anthropic S-1 的解读：招股书口径为增量毛利 90%、推理毛利 85%、连续两个季度盈利，Q1 净收入留存达 500%，收入同比涨 1368% 而算力费用只涨 300%。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-10-28T09:32:56.000Z","url":"https://x.com/SaitoWu/status/2115376256929948006"},{"id":"c5zdgpchio31r2911elz4bbg6","title":"Anthropic 上市文件披露四类芯片混用布局，分析师称英伟达定价权或承压","summary":"据《商业内幕》10 月 28 日报道，Anthropic 在 S-1 上市申请文件中披露，公司把多家战略合作伙伴的算力整合成统一资源池，通过软件将计算任务分配到亚马逊 Trainium、谷歌 TPU、英伟达 GPU 和 AMD GPU 四类芯片上，以分散风险。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-28T06:35:47.357Z","url":"https://www.ithome.com/1/018/906.htm"},{"id":"q287d5f1xom92gova9cmmlq5g","title":"Anthropic IPO 文件将潜在市场规模估为每年 40 万亿美元","summary":"据 WSJ 报道，Anthropic 在 IPO 文件中将潜在市场规模估为每年 40 万亿美元，超过 SpaceX 此前 28.5 万亿美元的估算。其做法是把 2025 年全球知识工作者创造的经济价值（超过 40 万亿美元）整体视为自身市场，理由是前沿 AI 能提升这些工作者的生产力从而扩大该价值。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T02:05:34.000Z","url":"https://x.com/rohanpaul_ai/status/2115263675124838643"},{"id":"b61d349yqp5mt029fsa0ytbv9","title":"Anthropic IPO 最大赢家或为 Amazon 而非 VC","summary":"TechCrunch 根据 Anthropic 的 S-1 分析，VC 持股均不足 5%，而 Amazon 可能是 IPO 最大财务受益方。Amazon 持有 62 亿美元本金可转债、其自估持仓价值 979 亿美元，另投 100 亿美元无投票权优先股，累计投资约 180 亿美元；Anthropic 还承诺未来 10 年在 AWS 至少消费 1100 亿美元。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-28T01:15:28.000Z","url":"https://techcrunch.com/2026/10/27/vcs-will-make-billions-on-anthropics-ipo-but-amazon-is-set-to-make-much-much-more/"},{"id":"lre38a418cjju32u8z01oxq7p","title":"Anthropic IPO 后的治理结构解析：LTBT 与创始人如何掌握控制权","summary":"TechCrunch 解析 Anthropic 上市后的公司治理结构，普通股股东对董事会组成等重大决策几乎没有话语权。Long Term Benefit Trust 持有特殊股票，可任免 4 个 Class T 董事席位中的多数，成员包括 Ben Bernanke 等；七位创始人以 50.1% 投票权选举 3 名董事。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T21:38:28.000Z","url":"https://techcrunch.com/2026/10/27/whos-really-in-charge-at-anthropic-after-the-ipo/"}]},"760e0591-91c2-4b7a-aea8-5a33ba5d86b1":{"publicId":"760e0591-91c2-4b7a-aea8-5a33ba5d86b1","title":"Anthropic 发布 Fable 5.2 与 Mythos 5.2，多项评测登顶","status":"active","sourceCount":36,"reportCount":74,"firstReportAt":"2026-11-08T16:00:00.000Z","latestAt":"2026-11-12T02:00:20.000Z","latest":"Claude Fable 5.2 登顶 AA-Robotics","digest":"Anthropic 发布 Claude Fable 5.2 和 Claude Mythos 5.2，两者基于同一底层模型。Fable 5.2 面向所有付费计划开放，内置拦截高风险网络安全与生物研究任务的防护；Mythos 5.2 移除部分限制，仅向通过网络安全或生命科学验证计划申请的组织开放。Fable 5.2 定价为每百万输入 token 8 美元、输出 40 美元，较 Fable 5.1 的 10/50 美元降 20%，支持 100 万 token 上下文，并已在 Claude Code、OpenRouter、Cursor、Perplexity、Google Cloud、OpenClaw 等平台上线。\n\n评测方面，Artificial Analysis 智能指数 v5 以 65 分登顶；Arena Code Arena: WebDev 以 1832 分居首；Remote Labor Index 以 41.3% 领跑；AA-Robotics v0.1 以 75 分居首，领先 GPT-6 Astra（69）和 GPT-6.1 Sol（65），并成为首个在测量盒任务上得分的模型。Arena 称 Fable 5.2 (Max) 以 +30.4% 净提升登顶 Agent Arena，约为第二名 Opus-5.5 的 1.6 倍，数据来自 4.7k 真实智能体会话。ARC Prize 公布其在 ARC-AGI-2 得 93.8%，为第三高，低于 GPT-6 Astra 的 95.0% 和 GPT-6.1 Sol 的 94.2%。Anthropic 称 Fable 5.2 解决了两个与黑洞相关的理论物理开放问题，包括一项 23 年未完成的计算。\n\n订阅权益上，Pro 用户获一次 Fable 重置，Max、Ultra 和 Team Premium 按订阅时长最多三次，可用至 3 月 8 日；Pro 和 Team Standard 另有一周试用期，额度不超过每周上限的一半。Addy Osmani 称该模型 token 消耗大，按单任务计成本与 Fable 5.1 大致相当。","digestUpdatedAt":"2026-11-12T02:14:18.795Z","reports":[{"id":"shb2cxiblvq7iuzx5ug97p4vi","title":"Latent Space AINews：Google 发布 Gemini Decision 1 决策模型，Claude Fable 5.2 登顶 Agent Arena","summary":"Latent Space 发布 AI 要闻汇总，核心是 Google 抢先 Anthropic 推出生产级校准多模态决策模型 Gemini Decision 1，单次前向完成封闭集决策，支持每请求最多 1000 个问题、256K 上下文，输入 $0.10/1M tokens 且输出免费，端到端延迟约 150–250ms。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-12T05:26:54.000Z","url":"https://latent.space/p/ainews-d-day-decision-models-day/"},{"id":"bo01it25cgvef1al6p8qo7es0","title":"Claude Fable 5.2 登顶 AA-Robotics","summary":"Claude Fable 5.2 成为 AA-Robotics v0.1 的新榜首，得分 75，领先于 GPT-6 Astra（69）和 GPT-6.1 Sol（65）\n\nFable 5.2 是首个在测量盒任务上取得分数的模型。它完全依靠视频完成，将卷尺作为布置，并利用其刻度作为比例来估算盒子尺寸","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-12T02:00:20.000Z","url":"https://x.com/ArtificialAnlys/status/2120698177016005029"},{"id":"jcostrwrefbi74nntek3ogscy","title":"Claude Fable 5.2 (Max) 以 +30.4% 净提升登顶 Arena Agent 榜首","summary":"Arena 宣布 Claude Fable 5.2 (Max) 登顶 Agent Arena，净提升 +30.4%，约为第二名 Opus-5.5（+19.5%）的 1.6 倍，数据来自 4.7k 真实智能体会话。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-11T17:23:38.000Z","url":"https://x.com/arena/status/2120568144687460434"},{"id":"a6ru61o5bfv0rr2xmfdohyajy","title":"Epoch Brief：GLM 5.3 自主攻破六个 Firefox 版本，Claude Fable 5.2 刷新 ECI 纪录","summary":"Epoch AI 实验显示，开源权重模型 GLM 5.3 在离线沙箱中自主为六个 Firefox 版本构建可用漏洞利用，每个成本约 1000 美元。Anthropic 于 11 月 9 日发布的 Claude Fable 5.2 在 Epoch Capabilities Index 上得分 174，超过 GPT-6 Astra 的 169，创下新纪录。","sourceName":"Epoch AI：Gradient Updates（RSS）","firstParty":true,"publishedAt":"2026-11-11T17:18:46.000Z","url":"https://epochai.substack.com/p/the-epoch-brief-november-11-2026"},{"id":"mw8wvasegu4xd60afqu6xvtau","title":"Claude Fable 5.2 现已在 OpenClaw 可用","summary":"OpenClaw 宣布 Anthropic 的 Claude Fable 5.2 现已可在 OpenClaw 中使用。据 Anthropic 介绍，该模型输出生成速度比 Fable 5.1 最快提升 30%，详情见 anthropic.com 的发布页面。","sourceName":"X：OpenClaw (@openclaw)","firstParty":false,"publishedAt":"2026-11-11T16:12:10.000Z","url":"https://x.com/openclaw/status/2120550160128467398"},{"id":"hl9vucjaloy0llz9kuc9kmvx3","title":"Anthropic 为 Claude Pro、Max、Ultra 和 Team 用户免费重置额度，并扩大 MCP Apps 支持","summary":"Anthropic 宣布为 Claude Pro、Max、Ultra 和 Team 用户提供一次覆盖所有模型和使用限制的免费完整额度重置，以弥补此前 Bug 导致的词元超额消耗，太平洋时间 12 月 10 日下午 2 点前可在 Settings > Usage 或 claude.de/reset 领取。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-11T01:51:02.380Z","url":"https://www.ithome.com/1/025/292.htm"},{"id":"rwalnzed63wo2h42emw4rq092","title":"Claude 向付费用户发放免费额度重置","summary":"好好享受这次重置 🧡\n\n我们还将 UI 改为显示确切的到期时间，这样你就不会错过，而且（希望）现在 Fable 重置的作用也更清楚了！","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-10T22:12:54.000Z","url":"https://x.com/lydiahallie/status/2120278551840920014"},{"id":"gzrrng5ry1y152tm2qc4d2h92","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2：同一模型、不同安全限制","summary":"Anthropic 发布 Claude Fable 5.2 和 Claude Mythos 5.2，两者是同一底层模型，Fable 5.2 增加拦截高风险网络安全和生物研究任务的分类器，Mythos 5.2 取消这些限制、需通过验证项目访问。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:59:09.000Z","url":"https://www.marktechpost.com/2026/11/10/anthropic-claude-fable-5-2-mythos-5-2-release/"},{"id":"oesqqhekbr8e1bekkcitpguqh","title":"Anthropic Fable 5.2 在 Remote Labor Index 上以 41.3% 领跑真实自由职业任务","summary":"The Decoder 报道，Anthropic 新模型 Fable 5.2 在 Scale Labs 和 Center for AI Safety 的 Remote Labor Index 基准上以 41.3% 排名第一，该测试衡量 AI 智能体能否把真实自由职业项目做到让付费客户接受的质量。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:07:47.000Z","url":"https://the-decoder.com/anthropics-fable-5-2-completes-41-percent-of-real-freelance-jobs-up-from-2-5-percent-a-year-ago/"},{"id":"hynj57ofu1z4qk45g0cau922d","title":"那些做机器人模型的公司 此刻是什么心情💢 会写代码和用工具的 LLM 吞噬一切😜","summary":"那些做机器人模型的公司 此刻是什么心情💢 会写代码和用工具的 LLM 吞噬一切😜","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-10T07:49:56.000Z","url":"https://x.com/indigox/status/2120061380892193023"},{"id":"nnl670lkd0mynnkspz9f1wmgp","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，重登榜首但每任务成本上升","summary":"Anthropic 发布 Claude Fable 5.2 和 Mythos 5.2，Fable 5.2 在 Artificial Analysis Intelligence Index v5 以 65 分登顶，超过 Gemini 4 Carbon 和 Opus 5.5。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-10T06:34:44.000Z","url":"https://latent.space/p/ainews-fable-5-2-retakes-world-1-llm-spot-as-ant-ipo-roadshow-begins/"},{"id":"ob980onmw1uvlrmardsbv4mbp","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，编码基准超 GPT-6 Astra","summary":"Anthropic 于 11 月 10 日发布 Claude Fable 5.2 与 Claude Mythos 5.2 两款模型，官方称输出速度最高提高 30%，成本下降 20%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T05:52:12.373Z","url":"https://www.ithome.com/1/024/796.htm"},{"id":"spldx7fx85cpl890x6b8gr5u9","title":"Claude Fable 5.2 登顶 Arena WebDev 榜，比 Fable 5.1 快 30% 且降价","summary":"Anthropic 的 Claude Fable 5.2 (xHigh) 以 1832 分登顶 Arena 的 Code Arena: WebDev 榜，超过 Claude Opus 5.5 (Max) 的 1818 和 Gemini 4 Carbon (High) 的 1768。该版本比 Fable 5.1 快至多 30%，价格从每 M tokens $10/$50 降至 $8/$40。Arena 同时发布了 17 个生成示例视频，涵盖 3D 世界、可玩游戏、网页 UI、数据可视化和代码生成的交互动画。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-10T00:19:40.000Z","url":"https://x.com/arena/status/2119948067449536733"},{"id":"lfw4cc14h85i07c00tah6pc90","title":"Simon Willison 更新 llm-anthropic 0.31 支持 Anthropic 新模型 Fable 5.2 与 Mythos 5.2","summary":"Simon Willison 发布 llm-anthropic 0.31，纳入 Anthropic 当日发布的 Fable 5.2 和 Mythos 5.2，并给出安装和调用命令。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-09T23:58:46.000Z","url":"https://simonwillison.net/2026/Nov/9/llm-anthropic/"},{"id":"ljc2f7hyvtplkggpez6tivvnz","title":"实测Claude Fable 5.2：审美与细节的长任务能力体验","summary":"卡兹克凌晨实测刚全渠道上线的Claude Fable 5.2，称其在视频动效、Three.js 3D和上海苹果静安店3D网页等任务中审美与细节表现突出，跑分AA指数65分登顶。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-09T23:53:55.000Z","url":"https://x.com/Khazix0918/status/2119941585538572390"},{"id":"u1n6sw21ocnfdd1sdbd4i9m7z","title":"Claude Fable 5.2 (xHigh) 以 1832 分登顶 Code Arena: WebDev 榜单","summary":"Anthropic 发布的 Claude Fable 5.2 (xHigh) 在 Arena 的 Code Arena: WebDev 榜单以 1832 分排名第一，超过 Claude Opus 5.5 (Max) 的 1818 分和 Gemini 4 Carbon (High) 的 1768 分。据 Arena 数据，该模型比 Fable 5.1 快最多 30%，价格从每百万 tokens $10/$50 降至 $8/$40，Agent Arena 分数即将公布。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T23:52:24.000Z","url":"https://x.com/arena/status/2119941204003770690"},{"id":"po2cdt1whxfqyfew3e81l8mb0","title":"实测 Claude Fable 5.2：一次直出视频与 3D 网页，审美与细节表现突出","summary":"Anthropic 凌晨正式发布 Claude Fable 5.2，作者第一时间实测视频动效、Three.js 3D 场景和苹果静安店 3D 网页等 10 个任务，全部一次直出，未发现生成视频中的事实错误。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-09T23:21:03.000Z","url":"https://mp.weixin.qq.com/s/sKoVHL_oNsik9vtUjr0lHg"},{"id":"yoiln3nl94gd0t3pahyhpl1xu","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，API 调用费下降 20%","summary":"Anthropic 于 11 月 9 日发布 Claude Fable 5.2 和 Claude Mythos 5.2，基于同一底层模型，前者面向普通用户，后者面向通过审核的网络安全和生命科学机构。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-09T23:14:28.957Z","url":"https://www.ithome.com/1/024/573.htm"},{"id":"dmwbvf5xa3txsm013y0pfgcgn","title":"Rohan Paul 转述 Claude Fable 5.2 完成 23 年未解的黑洞计算","summary":"Rohan Paul 转发 @claudeai 的消息称，Claude Fable 5.2 解决了两个与黑洞相关的理论物理开放问题，其中一项是悬置 23 年的繁琐计算。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T22:59:11.000Z","url":"https://x.com/rohanpaul_ai/status/2119927810517324048"},{"id":"h5nu7w8t9ueaz2etbcj5a2bzx","title":"Fable 5.2 token 消耗高，单任务成本与 5.1 相当","summary":"关于 Fable 5.2 需要说明一点：它的 token 消耗量很大。\n\n在我们的测试中，这通常意味着按单个任务计算，它的成本与 Fable 5.1 大致相同，尽管 token 单价便宜了 20%。\n\n提醒一下那些注意到降价的人！","sourceName":"X：Addy Osmani (@addyosmani)","firstParty":false,"publishedAt":"2026-11-09T21:37:08.000Z","url":"https://x.com/addyosmani/status/2119907165007945813"},{"id":"yn7rlom00o5fgdbcfssna1r04","title":"Claude Fable 5.2 视频能力演示：为 ChatGPT 四周年庆生","summary":"用户用 Claude Fable 5.2 为即将四周年的 ChatGPT 提前制作了一支庆生视频，称其视频能力又大幅进化，节奏和动效表现突出。推文未给出具体参数或评测数据，仅评价细节与节奏“强无敌”，并期待 OpenAI 后续拿出更好的产品。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-09T21:17:54.000Z","url":"https://x.com/Khazix0918/status/2119902325460590834"},{"id":"obzr8x05lsufq7bknpsxpxvlk","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，IPO 前重夺性能领先","summary":"Anthropic 发布 Claude Fable 5.2 和 Mythos 5.2，两模型同一基础但访问策略不同：Fable 带网络安全与生物安全护栏向所有用户开放，Mythos 移除部分限制，仅向通过 Verification Programs 申请的组织开放。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-09T21:15:23.000Z","url":"https://the-decoder.com/claude-fable-5-2-and-mythos-5-2-cement-anthropics-ai-lead-just-before-its-ipo/"},{"id":"v98n3a3ihdr862ehiug7tjqqe","title":"Claude Fable 5.2 在 Google Cloud 上线","summary":"Claude Fable 5.2 现已在 Google Cloud 可用，支持构建长时间运行的智能体。该版本面向跨多个仓库和 monorepo 的大型模糊问题、可持续数小时至数天的无人值守工作流（含子智能体协调），以及困难物理计算、形式化证明和数据分析等科学与数据流水线。","sourceName":"Google AI：DEV 作者专属（RSS）","firstParty":false,"publishedAt":"2026-11-09T21:15:16.000Z","url":"https://dev.to/googleai/claude-fable-52-is-available-on-google-cloud-15kn"},{"id":"eo8g3wddjvxgmw1c3rfnomgtd","title":"Claude Fable 5.2 视频能力演示：为 ChatGPT 四周年庆生","summary":"作者用 Claude Fable 5.2 为即将到来的 ChatGPT 四周年提前制作了一支庆生视频，称其视频能力又大幅进化，节奏和动效表现很强。推文未给出具体参数、分数或价格信息。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-09T21:08:05.000Z","url":"https://x.com/Khazix0918/status/2119899854323540238"},{"id":"qbgn6yju6qvr6i7mb4bkk8y77","title":"Anthropic 发布 Claude Fable 5.2，Claude Mythos 5.2 开放专项申请","summary":"Anthropic 宣布 Claude Fable 5.2 当日起面向所有付费计划开放。从事网络安全或生物医学研究有益应用的组织可申请访问 Claude Mythos 5.2，详情见 https://www.anthropic.com/claude-fable-and-mythos-5-2。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:39.000Z","url":"https://x.com/claudeai/status/2119899492778398163"},{"id":"ktl31hzsgulxlz6vbxolyldc9","title":"Fable 5.2 验证极小宇宙黑洞突变","summary":"1983年，物理学家证明，当某些更大的理论宇宙升温时，黑洞会非常突然地形成。2003年，有人提出了一项计算，用于检验这一现象在一组极小的宇宙中是否同样成立。\n\nFable 5.2 发现，那里的转变同样是突变的。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:38.000Z","url":"https://x.com/claudeai/status/2119899487044825293"},{"id":"p3jlan36o3hidm58amjwae14z","title":"Fable 5.2 破解模模块化自举极限","summary":"在第二个物理问题中，Fable 5.2 找到了被称为“模模块化自举”的 15 年历史技术最简单版本的精确极限。该技术用于在理论宇宙中排除量子引力的候选理论。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:38.000Z","url":"https://x.com/claudeai/status/2119899488995131439"},{"id":"lgplhadzt9g0f4s2s08eqyxah","title":"Fable 5.2 解决黑洞理论物理难题","summary":"Fable 5.2 解决了理论物理中两个与黑洞相关的开放问题。\n\n在第一个问题中，Fable 5.2 完成了一项长达 23 年未解出的繁重计算。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:37.000Z","url":"https://x.com/claudeai/status/2119899484373369278"},{"id":"w45lbhhprl6qnfys5jtkrszi5","title":"Claude 订阅用户重置次数说明","summary":"Pro 用户可获得一次重置，Max、Ultra 和 Team Premium 用户最多可获得三次，具体取决于你的订阅时长：\nhttps://support.claude.com/en/articles/17506494-claude-fable-5-2-launch-offers","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-09T20:32:11.000Z","url":"https://x.com/bcherny/status/2119890820186976763"},{"id":"trwrvd5kw6o78ulj98yggbvxc","title":"Higgsfield MCP 接入 Claude 试用 Fable 5.2","summary":"现在就在 Claude 中通过 Higgsfield MCP 试用 Fable 5.2：\nhttps://higgsfield.ai/mcp?tab=claude","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-09T20:06:54.000Z","url":"https://x.com/higgsfield/status/2119884456651866439"},{"id":"ugn21ui1m8kftffpe2c95qlkx","title":"Claude Fable 5.2 上线 Higgsfield，开放 3 天免费试用","summary":"Higgsfield 宣布 Claude Fable 5.2 已在 Higgsfield MCP 上线，提供 3 天免费不限量使用全部顶级视频和图像模型。作者称该 Anthropic 新模型擅长 3D 建模、视觉推理、computer use 和编码；引用内容提到 Claude Fable 5.2 与 Claude Mythos 5.2 在编码、推理和视觉方面有提升。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-09T20:06:53.000Z","url":"https://x.com/higgsfield/status/2119884452054937656"},{"id":"i2tveljooudnlde5gbtpps79q","title":"Claude Fable 5.2 上线 Agent Arena，用户可实测，评分即将公布","summary":"Arena 宣布 Anthropic 的 Claude Fable 5.2 已上线 Agent Arena，用户可前往实测，官方评分即将公布。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T19:58:21.000Z","url":"https://x.com/arena/status/2119882304718069874"},{"id":"shwr0td0cprvq5e36s0jmar7t","title":"Cursor 公布 Fable 5.2 定价与推理档位变化","summary":"Fable 5.2 定价为每百万输入 token 8 美元、每百万输出 token 40 美元，比 Fable 5.1 低 20%。\n\n其 effort 档位的行为与 Fable 5.1 不同，因此请从默认档位开始，不要沿用旧设置。\n\n对比各 effort 档位：https://cursor.com/evals","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-09T19:52:32.000Z","url":"https://x.com/cursor_ai/status/2119880841728000057"},{"id":"lwtt7st2cponcbtt0twrzlvr9","title":"Claude Fable 5.2 上线 Cursor，CursorBench 默认档得分 56.9%","summary":"Cursor 宣布 Claude Fable 5.2 现已在 Cursor 中可用。Fable 5.2 在默认推理力度下 CursorBench 得分 56.9%，高于 Fable 5.1 的 49.2%；在最高推理力度下以 60% 位居 CursorBench 榜首，默认档平均每任务成本为 $9.70。","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-09T19:52:29.000Z","url":"https://x.com/cursor_ai/status/2119880829212172509"},{"id":"m23i0fgxrk1t2gqysu6mqv82s","title":"Artificial Analysis 评测 Claude Fable 5.2：以 65 分登顶 Intelligence Index v5","summary":"Artificial Analysis 评测 Anthropic 发布的 Claude Fable 5.2，其在 Artificial Analysis Intelligence Index v5 以 65 分登顶，领先 Gemini 4 Carbon（60）和 Claude Opus 5.5（59）。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-09T19:45:12.000Z","url":"https://x.com/ArtificialAnlys/status/2119878995386982508"},{"id":"h2f58ke3re6fq8ottpst2kyev","title":"Fable 5.2 重置机制上线","summary":"太喜欢了。Fable 5.2 重置。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T19:38:51.000Z","url":"https://x.com/rohanpaul_ai/status/2119877395742437590"},{"id":"lr06w7ixk1mrwmiu8noiwrnrs","title":"Claude Fable 5.2 上线 Perplexity","summary":"Claude Fable 5.2 现已在 Perplexity Computer 中向 Pro 和 Max 订阅用户开放，并在 Search 中向 Max 订阅用户开放。\n\n在我们的 WANDR 基准测试中，它实现了性能与效率的帕累托前沿，以每任务 14.51 美元的成本创下 0.851 的纪录分数。","sourceName":"X：Perplexity (@perplexity_ai)","firstParty":false,"publishedAt":"2026-11-09T19:29:41.000Z","url":"https://x.com/perplexity_ai/status/2119875089974104489"},{"id":"yjtr1evpobvoxm47szz1h6dmf","title":"Claude Fable 5.2 上线 OpenRouter：1M 上下文，输入 $8/M、输出 $40/M","summary":"Anthropic 的 Claude Fable 5.2 上线 OpenRouter，定价为输入 $8/M、输出 $40/M，上下文 1M，输出速度比 Fable 5.1 快至 30%。Anthropic 公布的成绩包括 FrontierSWE v2 69.9%、OSWorld 2.1 89.3%、Humanity's Last Exam（带工具）74.2%，详情见 http://openrouter.ai/anthropic/claude-fable-5.2","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-09T19:29:40.000Z","url":"https://x.com/OpenRouter/status/2119875084521447767"},{"id":"vyl46w9gp41tiw4mavmq1nks0","title":"Anthropic 发布 Mythos 5.2 与 Fable 5.2，METR 报告引发 RSI 担忧","summary":"Anthropic 发布 Mythos 5.2 和 Fable 5.2，称新模型在编码、推理和视觉方面有提升。Fable 输入价格从每百万 token $10 降至 $8，低于竞争对手 GPT-6 Astra，响应速度提升 30%，并通过 Enterprise Frontier Safeguards 支持零数据保留（ZDR）政策。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T19:24:51.000Z","url":"https://techcrunch.com/2026/11/09/anthropic-releases-new-mythos-and-fable-models-amid-rsi-concerns/"},{"id":"qhzj0er5hgffkbmtnou3exjhx","title":"Claude 向订阅用户发放 Fable 重置次数","summary":"重置次数来了！","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-09T19:23:19.000Z","url":"https://x.com/adocomplete/status/2119873489679327578"},{"id":"r8v58z5d8lz5ro3q7j4yj90tq","title":"Claude Code v2.1.321 发布：新增 Claude Fable 5.2 为默认 Fable 模型","summary":"Claude Code 发布 v2.1.321，新增 Claude Fable 5.2（claude-fable-5-2）并设为默认 Fable 模型，支持 1M 上下文，价格为 $8/$40 per Mtok、缓存读取 $0.20/Mtok。","sourceName":"Claude Code：GitHub Releases（RSS）","firstParty":true,"publishedAt":"2026-11-09T19:22:30.000Z","url":"https://github.com/anthropics/claude-code/releases/tag/v2.1.321"},{"id":"y9k10za6wp1gxq3l2mvosharb","title":"Claude Fable 5.2 订阅越久重置越多","summary":"我们想为陪伴我们最久的用户多做些事。因此在 Fable 5.2 中，你订阅的时间越长，获得的 Fable 重置次数就越多。","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-09T19:21:45.000Z","url":"https://x.com/bcherny/status/2119873095129550880"},{"id":"vjeqe8ie59ggfas1bbursg3ao","title":"Anthropic 发布 Claude Fable 5.2 与 Claude Mythos 5.2","summary":"Anthropic 发布 Claude Fable 5.2 和 Claude Mythos 5.2，面向高难度技术挑战，在编码、推理和视觉等方面有提升。作者 Lydia Hallie 体验后认为它验证结果比 Fable 5.1 更彻底，并主要将其作为 orchestrator 搭配 Opus 5.5 使用；Pro/Max/Ultra/Team 套餐还获得至少一次免费 Fable reset。","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-09T19:16:05.000Z","url":"https://x.com/lydiahallie/status/2119871667400999166"},{"id":"q4hu7btrfoxga7slj6za15abz","title":"Fable 5.2 与 Opus 生成能力对比","summary":"对 @AnthropicAI 的 Fable 5.2 的第一印象来了。@petergostev 让它跑了 100+ 次生成，在 3D 世界、可玩游戏、网站 UI、数据可视化和动画方面与 Opus 进行对比。\n\nFable 5.2 在哪些方面有所提升，Opus 又仍在哪些方面更胜一筹，代价是什么？观看完整分析\nhttps://www.youtube.com/live/QwaU4yU0PdQ","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T19:15:48.000Z","url":"https://x.com/arena/status/2119871594403336451"},{"id":"ccr64nv9h7eryilvqf24aj22k","title":"ARC Prize 公布 Claude Fable 5.2 在 ARC-AGI-2 上取得 93.8%","summary":"ARC Prize 宣布 Claude Fable 5.2 在 ARC-AGI-2 上取得 93.8%，是其见过的第三高模型成绩，仅次于 GPT-6 Astra 的 95.0% 和 GPT-6.1 Sol 的 94.2%。完整结果见 https://arcprize.org/results/anthropic-claude-fable-5-2。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:46.000Z","url":"https://x.com/arcprize/status/2119871082756800545"},{"id":"vl2atp07nuiuo91hst8roouey","title":"ARC Prize 公布 Claude Fable 5.2 测试结果","summary":"@AnthropicAI - 排行榜：https://arcprize.org/leaderboard\n- 复现公开结果：https://github.com/arcprize/arc-agi-benchmarking\n- 测试政策：https://arcprize.org/policy\n- Claude Fable 5.2 完整结果：https://arcprize.org/results/anthropic-claude-fable-5-2","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:46.000Z","url":"https://x.com/arcprize/status/2119871084832915752"},{"id":"rvri367ocklyqxhy3evwkvxjn","title":"ARC Prize 公布 Claude Fable 5.2 在 ARC-AGI (Verified) 上的评测成绩","summary":"ARC Prize 发布 Claude Fable 5.2 在 ARC-AGI (Verified) 上的评测结果。ARC-AGI-3 得分 97.7%（成本 $18.6K，provider adapter harness）和 81.2%（成本 $21.9K，standard harness）；ARC-AGI-2 得分 93.8%（$0.98/task）；ARC-AGI-1 得分 98.5%（$0.36/task）。该模型在 standard harness 下创下 ARC-AGI-3 新高分之一（附 ARC-AGI 3 排行榜图）。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:45.000Z","url":"https://x.com/arcprize/status/2119871080525373922"},{"id":"uqzme96rbooud8mwvji044k7y","title":"ARC-AGI-3 测试中 max 推理受限","summary":"在标准测试框架下以 max 推理运行时，55 个半私有游戏中有 28 个达到了 12 小时的运行时限，限制了测试能推进的程度。max 在 ARC-AGI-3 上得分 65.7%，而 xhigh 为 81.2%；若无时限限制，我们预计 max 的得分会更高。\n\n另请注意，已发布的 Fable 5.2 在 medium 和 xhigh 推理强度下使用的调优与我们此前评估的检查点不同。low、high 和 max 未变。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:45.000Z","url":"https://x.com/arcprize/status/2119871081817284743"},{"id":"o7x1sg2wsppy841z3n0hk9grk","title":"Anthropic 发布 Claude Fable 5.2 与 Claude Mythos 5.2","summary":"Anthropic 推出 Claude Fable 5.2 和 Claude Mythos 5.2，主打编码、推理和视觉能力提升。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T19:09:53.000Z","url":"https://x.com/rohanpaul_ai/status/2119870108223033374"},{"id":"u23txiafgf94qjm5yg114bh89","title":"Perplexity 上线 Fable 5.2","summary":"Fable 5.2 现已在 Perplexity 上线。可在 Computer 中使用它，或用 Fable 创建 Teammates。在 Wide and Deep Research 任务（WANDR）上，Fable 以明显优势击败 Gemini Argon。","sourceName":"X：Aravind Srinivas（Perplexity CEO） (@AravSrinivas)","firstParty":false,"publishedAt":"2026-11-09T19:09:42.000Z","url":"https://x.com/AravSrinivas/status/2119870062408691902"}]},"e16f5d00-5477-42b8-83d3-4162e0262249":{"publicId":"e16f5d00-5477-42b8-83d3-4162e0262249","title":"Google 开放 Gemini 4 Carbon，Perplexity 同步上线","status":"active","sourceCount":17,"reportCount":24,"firstReportAt":"2026-10-30T20:19:56.000Z","latestAt":"2026-11-11T22:53:02.000Z","latest":"Google 员工测试 Gemini 4 Carbon 成果展示","digest":"Google 正式开放 Gemini 4 Carbon，称其为最强推理模型，主打长程智能体工作流、软件工程、科学推理和网络安全防御。付费开发者和企业可通过 Google AI Studio、Android Studio 的 Gemini API 及 Gemini for business 使用；Google AI Ultra 订阅者可在 Gemini App、搜索 AI Mode、Antigravity 和 AI Studio 使用。入门价为每百万输入 token 2 美元、每百万输出 token 10 美元，优惠至 2026 年 11 月 30 日，此后将调至 4 美元和 20 美元。The Verge 称尚不清楚更低档订阅或免费用户何时能用。\n\n该模型此前两周仅向 Fairwind 项目的网络安全防御者开放。Google 的 Logan Kilpatrick 称，因模型具备前沿网络能力，团队在安全部署上做了额外工作。The Decoder 指出，Carbon 与 Gemini 4 Argon 单价相同，但推理消耗更多 token，实际总成本可能更高。\n\nPerplexity CEO Aravind Srinivas 称已向所有 Pro 和 Max 订阅者推出 Carbon，可用于创建持久 Teammates 或在 Computer 中进行一次性智能体会话；他称其在 WANDR 基准上得分 0.857、每任务成本 5.86 美元，而 Claude Fable 5.2 为 0.851 分、14.51 美元。Every 的评测则称 Carbon 编码强于 Argon，但判断力仍跟不上。","digestUpdatedAt":"2026-11-11T23:14:10.468Z","reports":[{"id":"hcq5ofij70eoy51cs9ekr316j","title":"Google 员工测试 Gemini 4 Carbon 成果展示","summary":"过去几周，Google 员工一直在测试和探索 Gemini 4 Carbon。以下是我们最喜欢的几个案例 🧵\n\n为了捕捉这个 3D 水下蜂群的光影与运动，@fofrAI 使用 Carbon 从零构建了一个自定义的 CUDA 和 C++ 视觉特效引擎。https://x.com/fofrAI/status/2120188535152222407/video/1","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-11T22:53:02.000Z","url":"https://x.com/Google/status/2120651039636426878"},{"id":"rmyh61drfatbxzpvef0gew7kz","title":"谷歌开放 Gemini 4 Carbon 模型，主打复杂编程、科学研究与网络安全","summary":"谷歌于当地时间 11 月 10 日宣布正式开放 Gemini 4 Carbon 模型，面向开发者、企业、科研人员和消费者提供服务，定位为谷歌目前能力最强的推理模型。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T22:43:37.660Z","url":"https://www.ithome.com/1/025/203.htm"},{"id":"t1v305wrur6qhtvg58936ltf7","title":"Gemini 4 Carbon 全量开放，llm-gemini 0.36 发布并附实测","summary":"Simon Willison 介绍 llm-gemini 0.36，Gemini 4 Carbon 在两周前面向部分网络防御者后现已全量开放。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-10T20:09:44.000Z","url":"https://simonwillison.net/2026/Nov/10/llm-gemini/"},{"id":"rm4rl4rx94ych4od7170jns2k","title":"Google Gemini 4 Carbon 正式开放，网络安全与成本表现成为亮点","summary":"Google 正式发布 Gemini 4 Carbon，定位为补充而非替代 Gemini 4 Argon，面向复杂多步编码、调试和开放性科研等高智能任务，两者 token 单价相同但 Carbon 推理消耗更多 token，实际总成本可能更高。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-10T18:19:13.000Z","url":"https://the-decoder.com/gemini-4-carbon-arrives-just-in-time-to-feel-like-yesterdays-news-in-the-fastest-model-cycle-yet/"},{"id":"q3suwqyg7f2j9irr9pmc6rdw6","title":"Google DeepMind 推出 Gemini 4 Carbon，面向 Ultra 订阅者和付费开发者开放","summary":"Google DeepMind 宣布 Carbon 开始推送，称其能解决需要持续推理的问题，如综合密集多模态文件、构建交互式 3D 网页体验和发现软件漏洞。","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-10T18:17:45.000Z","url":"https://x.com/GoogleDeepMind/status/2120219374388924610"},{"id":"fc7s8m6wnq619c5s23tm57jsz","title":"Google DeepMind 开放 Gemini 4 Carbon 构建主打复杂长程任务","summary":"Google DeepMind 宣布开放 Gemini 4 Carbon 构建，称其为面向复杂、长程任务的最强模型。该模型旨在深入探索问题并运行长时间的验证循环，适用于软件工程、网络安全、知识工作和科学领域。","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-10T18:17:44.000Z","url":"https://x.com/GoogleDeepMind/status/2120219371473617099"},{"id":"bhlwz28hksdkul0f8b5pexdfq","title":"Demis Hassabis 宣布 Gemini 4 Carbon 已可用并附官方博客链接","summary":"Google 的 Demis Hassabis 发推宣布 Gemini 4 Carbon 现已可用，附上官方博客链接 https://blog.google/innovation-and-ai/models-and-research/gemini-models/gemini-4-carbon-now-available/，欢迎开发者上手构建。","sourceName":"X：Demis Hassabis (@demishassabis)","firstParty":false,"publishedAt":"2026-11-10T17:41:41.000Z","url":"https://x.com/demishassabis/status/2120210299643208084"},{"id":"k6hsd1wl71nhdxi6tnp6i4qhk","title":"Google 发布 Gemini 4 Carbon 前沿模型","summary":"Google 发布最新前沿模型 Gemini 4 Carbon，Demis Hassabis 称从 Gemini 3 到 Gemini 4 进展惊人。他演示 Carbon 一次性逆向自己 90 年代的 Theme Park 二进制文件、新增 DeepMind 主题游乐设施并移植到网页版。引用内容提到其在 Google AI Studio 中用 Gemini 3 在几小时内复刻了 Theme Park 测试版，玩家甚至可调整薯条加盐量。","sourceName":"X：Demis Hassabis (@demishassabis)","firstParty":false,"publishedAt":"2026-11-10T17:41:41.000Z","url":"https://x.com/demishassabis/status/2120210297948696997"},{"id":"x2fhum4l4h8foqc6fekpmdt3a","title":"Perplexity 向 Pro 和 Max 订阅者推出 Gemini 4 Carbon","summary":"Perplexity CEO Aravind Srinivas 宣布向所有 Pro 和 Max 订阅者推出 Gemini 4 Carbon，可用于创建持久 Teammates 或在 Computer 中进行一次性智能体会话。他称 Carbon 在智能体研究任务上能力与 Fable 5.2 相当，价格便宜 2.5 倍。配图 WANDR 基准显示 Gemini 4 Carbon 得分 0.857、每任务成本 $5.86，Claude Fable 5.2 得分 0.851、成本 $14.51。","sourceName":"X：Aravind Srinivas（Perplexity CEO） (@AravSrinivas)","firstParty":false,"publishedAt":"2026-11-10T17:34:22.000Z","url":"https://x.com/AravSrinivas/status/2120208455965569262"},{"id":"p2foff6y5z57pwz82kedvwetc","title":"Google 向所有付费开发者和 AI Ultra 订阅者开放 Gemini 4 Carbon","summary":"Google 向所有付费开发者和 Google AI Ultra 订阅者开放其最强模型 Gemini 4 Carbon，此前两周仅限 Fairwind 网络安全防御者使用。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T17:19:46.000Z","url":"https://x.com/rohanpaul_ai/status/2120204781491040287"},{"id":"wlkvqmxsknzw7w5htai1atjwy","title":"Google AI 宣布 Gemini 4 Carbon 已可用","summary":"Google AI 发布推文，宣布 Gemini 4 Carbon 现已可用，并附上博客链接 https://blog.google/innovation-and-ai/models-and-research/gemini-models/gemini-4-carbon-now-available/ 供了解更多信息。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-10T16:12:36.000Z","url":"https://x.com/GoogleAI/status/2120187881537020079"},{"id":"nrff1eq2gmg4sxcm7nx2rk703","title":"Google 发布最强前沿模型 Gemini 4 Carbon","summary":"Google 宣布最强前沿模型 Gemini 4 Carbon 正式可用，定位于复杂长程工作流，覆盖智能体工作、软件工程、网络安全和科学推理。Gemini 4 Argon 仍是多数软件工程和知识工作的理想选择，Carbon 面向多步调试、开放式科研等最难任务。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-10T16:12:06.000Z","url":"https://x.com/GoogleAI/status/2120187753329791341"},{"id":"j4oyn7yeh9zecoy3bpdtrq3i7","title":"Google 官方说明 Gemini 4 Carbon 因前沿网络能力而加强安全部署","summary":"Logan Kilpatrick 发文表示该模型具备前沿水平的网络（cyber）能力，团队一直在努力确保它能安全地部署给网络防御者和更广泛用户，并感谢用户的耐心等待。他同时欢迎继续反馈，承诺持续更新，附博客链接 https://blog.google/innovation-and-ai/models-and-research/gemini-models/gemini-4-carbon-now-available/。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-10T16:07:53.000Z","url":"https://x.com/OfficialLoganK/status/2120186693320057208"},{"id":"rvo5fyzeanu07hy3ibf5dlebi","title":"Google 发布 Gemini 4 Carbon，面向 Google AI Ultra 订阅用户开放","summary":"Google 宣布 Gemini 4 Carbon 从今天起向 Google AI Ultra 订阅用户开放，覆盖桌面端、移动端和网页端 gemini.google。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-10T16:06:55.000Z","url":"https://x.com/GeminiApp/status/2120186450927038900"},{"id":"oqugrm8zbsytjx54cetwbjwqp","title":"Google 发布 Gemini 4 Carbon，AI Ultra 订阅者与开发者均可使用","summary":"Google 宣布 Gemini 4 Carbon 从今日起可用。Google AI Ultra 订阅者可在 Gemini App、搜索 AI Mode、Antigravity 和 Google AI Studio 中使用；开发者和企业可通过 Google AI Studio 与 Android Studio 中的 Gemini API 以及 Gemini for business 使用。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-10T16:05:53.000Z","url":"https://x.com/Google/status/2120186190905090406"},{"id":"flpm7o54395qp9gja1dqxll3r","title":"Google 发布 Gemini 4 Carbon，定位最强模型","summary":"Google 宣布 Gemini 4 Carbon 正式可用，称其为最强模型，面向深度挖掘、长程任务和多步推理。官方表示 Argon 适合复杂任务，Carbon 则用于解决最难的问题。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-10T16:05:52.000Z","url":"https://x.com/Google/status/2120186185423159331"},{"id":"a191cqnvijne721sh75zupdjw","title":"Google 发布 Gemini 4 Carbon，已开放 Gemini API 和 Ultra 订阅","summary":"Logan Kilpatrick 宣布 Gemini 4 Carbon 上线，可通过 Gemini API 使用，Ultra 订阅用户也可用。他表示该模型在 Argon 发布几周后推出，针对 Argon 的多项反馈做出显著改进，并在网络安全、知识工作和代码方面推进前沿水平。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-10T16:05:12.000Z","url":"https://x.com/OfficialLoganK/status/2120186016254624039"},{"id":"w8cvkd1j2o1c3m8ikh8x2kpfx","title":"Google DeepMind 发布 Gemini 4 Carbon 前沿模型","summary":"Google DeepMind 正式向开发者、企业、科学家和普通用户开放 Gemini 4 Carbon，定位为其最强前沿模型，主打网络安全能力与复杂知识工作、软件工程、科学推理中的长程智能体工作流。","sourceName":"Google DeepMind：Blog（RSS）","firstParty":true,"publishedAt":"2026-11-10T16:03:47.000Z","url":"https://deepmind.google/blog/gemini-4-carbon-is-now-available/"},{"id":"zcwc57ndyas8laj8c8blsdk1n","title":"Google 面向公众发布 Gemini 4 Carbon，并在 Antigravity 预览 agent swarm 功能","summary":"Google 将 Gemini 4 Carbon 向公众开放，此前两周仅提供给部分网络安全防御者，并在 Antigravity 平台预览 swarm 功能，可将单个提示词变成协作的智能体团队。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T16:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030787/google-gemini-4-carbon-public-rollout"},{"id":"uge7vmdt81ghiucu1js6ithof","title":"Gemini 4 Carbon (gemini-4-carbon) 正式发布 GA","summary":"Google 发布 Gemini 4 Carbon（gemini-4-carbon）正式可用版本，定位为其最强推理模型，面向持续智能体编码、多模态知识工作、科学推理和网络安全防御。2026 年 11 月 30 日前提供入门价 $2.00 per 1M input tokens、$10.00 per 1M output tokens。","sourceName":"Gemini API：更新日志（网页）","firstParty":true,"publishedAt":"2026-11-10T00:00:00.000Z","url":"https://ai.google.dev/gemini-api/docs/changelog#11-10-2026"},{"id":"cs7o4n891nsyi6joa53yfh6nz","title":"Vibe Check 评测：Gemini 4 Carbon 编码更强但判断力跟不上","summary":"Every 发布对 Google DeepMind Gemini 4 Carbon 的评测，称其编码能力明显强于 Gemini 4 Argon，能生成立体度更好的三维物体，并可在少监督下连续工作数小时。","sourceName":"Every：最新文章（网页）","firstParty":false,"publishedAt":"2026-11-09T16:00:00.000Z","url":"https://every.to/vibe-check/vibe-check-gemini-4-carbon-doesn-t-know-when-to-stop"},{"id":"lwo8f2xyj01aujfmy02fk2ud4","title":"Google 发布 Gemini 4 Carbon，主打前沿网络安全与长程智能体工作流","summary":"Google 发布 Gemini 4 Carbon，面向开发者、企业、科学家和消费者开放，定位为在网络安全和跨知识工作、软件工程、科学推理的长程智能体工作流上性能最强的模型，定价与 Gemini 4 Argon 相同，为每百万输入 token $2、每百万输出 token $10。","sourceName":"Hacker News：AI 热帖","firstParty":false,"publishedAt":"2026-11-09T16:00:00.000Z","url":"https://blog.google/innovation-and-ai/models-and-research/gemini-models/gemini-4-carbon-now-available/"},{"id":"vu40ylaur67hzn3p1mcleaamn","title":"This Week in AI：Gemini 4 Carbon、Mistral Large 4 等新模型发布，投资者质疑 AI 支出","summary":"Google 发布面向网络安全与多步任务的 Gemini 4 Carbon，Mistral 公开万亿参数 Large 4（“Le Chonk”）权重，Google DeepMind 预览世界模型 Genie 4。","sourceName":"O'Reilly Radar（热点 RSS）","firstParty":false,"publishedAt":"2026-11-06T16:55:06.000Z","url":"https://www.oreilly.com/radar/this-week-in-ai-the-cost-of-progress/"},{"id":"fry3sr67xoubgdxura6c3js34","title":"Perplexity 分享 Gemini 4 Carbon 早期评测","summary":"分享 Gemini 4 Carbon 的早期评测。这是我们目前见过的在长篇幅研究和回答质量方面最强的模型，在 Wide-And-Deep-Research（WANDR）基准上取得了新的 SoTA。一旦我们拥有足够的 token 容量，所有 Perplexity Pro 和 Max 用户将可在 Computer 中使用。恭喜 @GoogleDeepMind！","sourceName":"X：Aravind Srinivas（Perplexity CEO） (@AravSrinivas)","firstParty":false,"publishedAt":"2026-10-30T20:19:56.000Z","url":"https://x.com/AravSrinivas/status/2116263856628703247"}]},"532d299f-c029-4fd3-8dcf-d821dd59a569":{"publicId":"532d299f-c029-4fd3-8dcf-d821dd59a569","title":"美联航封禁个人AI智能体代客订票","status":"active","sourceCount":5,"reportCount":5,"firstReportAt":"2026-11-11T18:28:24.000Z","latestAt":"2026-11-12T17:17:58.000Z","latest":"美联航以网络安全风险为由封禁 AI 智能体订票","digest":"美联航宣布不允许个人 AI 智能体代用户购票或管理预订，理由是网络安全风险、隐私泄露、误购风险，以及可能违反联邦法规。智能体仍可查询航班选项和价格，但无法在其网站完成购买。美联航称，联邦法规要求乘客亲自确认托运行李不含违禁物，AI 智能体无法合法执行；共享账号凭证还可能泄露敏感信息，或导致非预期购买、账户变更和里程被使用。\n\n美联航称，将在其数字平台以及旅行社和聚合平台渠道，直接和间接禁止未授权 AI 助手访问，并更新预订、出票和分销政策。据《华尔街日报》报道，CEO Scott Kirby 表示不想再制造一个中间商；美联航称未来会视第三方智能体的进展重新评估这一决定。eBay 和多家银行也对未授权智能体设置了类似限制。\n\nxAI 工程师 Lingxi Li 转发 Kalshi 关于此事的快讯并评论称，美联航禁止 AI 智能体预订航班是一个“大错误”。","digestUpdatedAt":"2026-11-12T18:28:18.199Z","reports":[{"id":"vsfksfgk0lbaxg53ohn53hh73","title":"美联航以网络安全风险为由封禁 AI 智能体订票","summary":"美联航宣布将限制第三方个人 AI 智能体代用户订票和管理预订，理由是网络安全风险和可能违反联邦法规。航空公司将在其数字平台以及旅行社和聚合平台渠道直接和间接禁止未授权 AI 助手访问，并更新预订、出票和分销政策。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T17:17:58.000Z","url":"https://techcrunch.com/2026/11/12/united-airlines-blocks-ai-agents-from-booking-flights-citing-cybersecurity-risks/"},{"id":"lm5ubbjb2qb9xoq4oczfhouac","title":"美联航禁止 AI 智能体代旅客购票：可查航班但不能下单","summary":"美国联合航空出于隐私和监管考虑，宣布不允许个人 AI 助手代旅客购买机票，AI 仍可展示航班但不能替用户完成交易。美联航担心智能体泄露客户信息、误解用户意愿下单，且行李确认等合规程序难以由 AI 代办；CEO 斯科特·柯比还表示不想再增加一个交易中间人。The Verge 指出 eBay 和多家大型银行也有类似限制，此类门槛可能压缩 AI 助手从提供建议走向代办交易的实际用途。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T01:39:34.963Z","url":"https://www.ithome.com/1/025/879.htm"},{"id":"i6gf8oojo2hn5v61a1tg2vfk9","title":"United 禁止 AI 智能体代客订票","summary":"United 宣布不允许个人 AI 智能体代用户完成购票交易，理由是隐私、误购风险以及可能绕开航空公司须向乘客披露信息的联邦规定，智能体仍可查询航班但不能完成交易。据 The Wall Street Journal 报道，CEO Scott Kirby 表示不想再制造一个中间商，United 称未来会视第三方智能体的进展重新评估；eBay 和多家银行也对未授权智能体设置了类似限制。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T21:54:21.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031623/united-unauthorized-ai-agents"},{"id":"o8qe4hn29tpvicv6k2mp22f69","title":"xAI 工程师评论 Kalshi 快讯称美联航禁止 AI 智能体订票是个错误","summary":"Lingxi Li 转发 Kalshi 的快讯并评论称，美联航禁止 AI 智能体预订航班是一个 big mistake。快讯称 United Airlines 禁止 AI agents 预订航班。","sourceName":"X：Lingxi Li（SpaceXSI，Grok Bot 工程） (@lingxi)","firstParty":false,"publishedAt":"2026-11-11T20:48:41.000Z","url":"https://x.com/lingxi/status/2120619746370699585"},{"id":"lri5bifxkd8qgt8rtecq6zvti","title":"美联航将禁止个人 AI 智能体在其系统购票","summary":"据 WSJ 报道，美联航将阻止个人 AI 智能体在其系统上预订机票，理由是它们可能泄露敏感数据或造成非预期购买。AI 智能体可读取航班选项和价格，但无法在其网站完成任何购买；联邦法规要求乘客亲自声明托运行李不含爆炸物，这是 AI 智能体无法合法执行的步骤。其后端系统已按来源标记每个预订，可区分个人、旅行社和 AI 智能体。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T18:28:24.000Z","url":"https://x.com/rohanpaul_ai/status/2120584444247760983"}]},"60c71184-5d0c-4286-94d2-52e32d087f39":{"publicId":"60c71184-5d0c-4286-94d2-52e32d087f39","title":"豆包工作向企业开放第三方模型并推限时优惠","status":"active","sourceCount":2,"reportCount":2,"firstReportAt":"2026-10-29T11:34:23.753Z","latestAt":"2026-11-12T02:31:16.000Z","latest":"豆包工作接入 Kimi K3.1 Pro、GLM 5.3、DeepSeek V4.1 Flash 等第三方模型并推出限时特惠","digest":"豆包工作向团队订阅版和企业订阅版客户开放第三方模型服务，首批接入 Kimi K3.1 Pro、GLM 5.3、DeepSeek V4.1 Flash 等模型，上线后默认开启。企业无需另行向模型厂商采购或额外申请，按用量扣除已有 AI 点数，并可按成员、部门、群组或全员划定可用范围，按厂商批量启用或单独配置模型。\n\n后续更新中，豆包工作将上述第三方模型与豆包 2.1 Lite、Pro 并列供选择，并在模型选择页面标注额度消耗倍率。豆包工作称，用户在工作日及节假日的指定优惠时段使用参与活动的模型可享额度消耗优惠；豆包 2.1 Lite 和 DeepSeek V4.1 Flash 的额度消耗倍率已下调；新用户登录电脑版可免费领取 30 天订阅权益。","digestUpdatedAt":"2026-11-12T02:43:22.738Z","reports":[{"id":"a5v0ikr6ow2l9rpcvbi77jqi5","title":"豆包工作接入 Kimi K3.1 Pro、GLM 5.3、DeepSeek V4.1 Flash 等第三方模型并推出限时特惠","summary":"豆包工作产品更新，在豆包2.1 Lite和Pro之外新增Kimi K3.1 Pro、GLM 5.3、DeepSeek V4.1 Flash等多款第三方模型，并在模型选择页面标注额度消耗倍率。同时推出限时优惠活动，工作日及节假日指定时段使用参与活动的模型可享额度消耗优惠，豆包2.1 Lite和DeepSeek V4.1 Flash的额度消耗倍率也已下调。新用户登录电脑版可免费领取30天订阅权益。","sourceName":"公众号：豆包（字节）","firstParty":false,"publishedAt":"2026-11-12T02:31:16.000Z","url":"https://mp.weixin.qq.com/s/sJ3FeTQoTXWXobzaflIwWQ"},{"id":"umle6dgudhf73hxhvypmv4qk8","title":"豆包工作向企业客户开放第三方模型服务，接入 Kimi 3.1 Pro、GLM 5.3、DeepSeek V4.1 Flash","summary":"豆包工作今日宣布向企业客户开放第三方模型服务，首批接入 Kimi 3.1 Pro、GLM 5.3、DeepSeek V4.1 Flash 等系列模型。该服务面向团队订阅版和企业订阅版客户，上线后默认开启，企业无需另行向模型厂商采购或额外申请，按用量扣除已有 AI 点数。企业还可按成员、部门、群组或全员划定可用范围，按厂商一键批量启用或单独配置单一模型。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-29T11:34:23.753Z","url":"https://www.ithome.com/1/019/733.htm"}]},"315f4328-e4b0-4d44-bc5e-e317e0b0f8f6":{"publicId":"315f4328-e4b0-4d44-bc5e-e317e0b0f8f6","title":"DeepMind 发布 AlphaGenome 2 基因组模型","status":"active","sourceCount":8,"reportCount":14,"firstReportAt":"2026-11-11T15:00:00.000Z","latestAt":"2026-11-12T12:09:43.000Z","latest":"Google DeepMind 发布 AlphaGenome 2，将基因组 AI 从组织级预测推进到单细胞类型分辨率","digest":"Google DeepMind 发布下一代 DNA 序列模型 AlphaGenome 2，称其能预测 DNA 变异如何影响特定人类细胞类型和细胞状态中的基因表达。DeepMind 称，模型改用条件式架构，训练数据超过 1.07 亿个单细胞样本、覆盖 68 种组织；在 TenK10K 数据集上识别出的因果变异数量接近上一代的两倍（30% 对 16%）。\n\nDeepMind 称，模型无需重新训练即可适配新的单细胞实验：研究人员接入几十个细胞的数据，就能观察 DNA 变化在特定时刻的表现，例如免疫细胞对疫苗的响应、肠道细胞驱动炎症性疾病、干细胞成熟为血细胞。\n\n模型已通过 AlphaGenome API 开放，限非商业研究使用，并提供交互式 Colab 教程；商业研究仅限“private preview”（非公开预览）。DeepMind 注明，该模型仅供研究使用，尚未经临床或诊断用途验证或批准。上述能力均为 DeepMind 的说法。","digestUpdatedAt":"2026-11-12T12:47:16.993Z","reports":[{"id":"j31f80nm7itk58ko1dmjg8ecy","title":"Google DeepMind 发布 AlphaGenome 2，将基因组 AI 从组织级预测推进到单细胞类型分辨率","summary":"Google DeepMind 发布基因组研究 AI 模型 AlphaGenome 2，可预测 DNA 变异对特定人类细胞类型的影响。该模型以特定生物状态为额外输入的条件模型，基于来自 68 种组织的超过 1.07 亿个单细胞图谱训练；在 TenK10K 基准上识别约 30% 的因果变异，微调版前代仅 16%。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-12T12:09:43.000Z","url":"https://the-decoder.com/google-deepmind-shifts-genomics-ai-from-bulk-tissue-predictions-to-single-cell-type-resolution-with-alphagenome-2/"},{"id":"qe4g0jps0j1hg5kbz2u0i3kkn","title":"AlphaGenome 2 如何助力罕见病基因研究","summary":"找到罕见病的精确遗传病因，就像大海捞针。🪡\n\n在我们的播客中，@fryrsquared 与 @Avsecz 和 @adamgayoso 一起探讨 AlphaGenome 2 如何帮助科学家测试数百万个 DNA 变化，为人类健康寻找关键线索。\n\n时间轴：\n00:00 AlphaGenome 介绍\n04:01 基因型、表型与 DNA\n08:30 从 Transformer 到 AlphaGenome\n12:11 基因组图谱绘制\n17:45 罕见病案例\n21:10 AlphaGenome 2\n30:06 未来愿景\n38:45 Hannah 的想法","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-12T11:31:32.000Z","url":"https://x.com/GoogleDeepMind/status/2120841923237683462"},{"id":"ikobtpz1wzu4psmio9lm3ydi0","title":"Google DeepMind 发布 AlphaGenome 2：深入单细胞分析，识别基因表达变异能力接近翻倍","summary":"Google DeepMind 于 11 月 11 日发布新一代基因组 AI 模型 AlphaGenome 2，可将组织、细胞类型或状态作为输入，预测 DNA 序列及变异对特定细胞的影响。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-11T23:28:24.857Z","url":"https://www.ithome.com/1/025/840.htm"},{"id":"iyjgod7fuxf7x9z4ehtijy45r","title":"Google DeepMind 发布 AlphaGenome 2，按细胞类型预测 DNA 变异效应","summary":"Google DeepMind 发布 DNA 模型 AlphaGenome 2，可输入 1 Mb DNA 加目标细胞状态，按细胞类型预测变异效应，通过 AlphaGenome API 向非商业研究开放。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-11T20:51:56.000Z","url":"https://www.marktechpost.com/2026/11/11/google-deepmind-alphagenome-2-cell-type-variant-effects/"},{"id":"hq6xo30x45z0tfmw7gykqfqyf","title":"Google DeepMind 发布 DNA 序列模型 AlphaGenome 2","summary":"Google DeepMind CEO Demis Hassabis 宣布发布新 DNA 序列模型 AlphaGenome 2，可预测 DNA 变异对不同特定细胞类型的影响，为理解复杂疾病提供关键信息。模型已通过 API 向学术研究开放，地址为 https://www.alphagenomedocs.com/。","sourceName":"X：Demis Hassabis (@demishassabis)","firstParty":false,"publishedAt":"2026-11-11T17:12:24.000Z","url":"https://x.com/demishassabis/status/2120565316619284734"},{"id":"m131gsazqedcd55oivr9hr61b","title":"AlphaGenome 2 开放非商业研究使用","summary":"AlphaGenome 2 今日起可通过 AlphaGenome API 用于非商业研究 https://deepmind.google/blog/alphagenome-2-deciphering-how-cells-read-dna-to-better-understand-disease/","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-11T16:23:47.000Z","url":"https://x.com/sundarpichai/status/2120553082430144866"},{"id":"u2ayukhmd1iptylota14ty0rm","title":"Google DeepMind 发布 AlphaGenome 2 预测 DNA 变异对特定细胞类型的影响","summary":"Google DeepMind 发布 AlphaGenome 2，帮助科学家预测 DNA 变异如何影响特定细胞类型，并揭示疾病的细胞层面成因。模型基于同一 DNA 蓝图在不同细胞类型中解读方式不同的原理，预测特化细胞如何解读 DNA；相比 AlphaGenome 1，研究人员更容易把基因发现与疾病实际发生的特定细胞中的根本原因关联起来。","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-11T16:23:46.000Z","url":"https://x.com/sundarpichai/status/2120553080232329324"},{"id":"ndavpsseus13b45d3l89zz1ps","title":"谷歌 DeepMind 发布 AlphaGenome 2 基因序列模型，识别致病变异能力提升近一倍","summary":"谷歌 DeepMind 发布新一代 DNA 序列模型 AlphaGenome 2，可将预测从宽泛组织缩小到单个细胞类型与状态，识别可改变基因表达的变异数量较初代接近翻倍。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-11T15:28:08.323Z","url":"https://www.ithome.com/1/025/822.htm"},{"id":"j2lu1jqfe2amju4n1z4fswo58","title":"Google DeepMind 发布 AlphaGenome 2，可预测同一 DNA 在不同细胞中的差异读取","summary":"Google DeepMind 发布 AlphaGenome 2，能预测相同 DNA 在不同细胞中被差异读取的方式，为理解人类遗传学提供新的可能性。模型现可通过 API 和交互式 Colab 教程供非商业研究使用，详情见 https://goo.gle/4zikg3w。","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-11T15:03:19.000Z","url":"https://x.com/GoogleDeepMind/status/2120532832145576242"},{"id":"n2qtugrkstr6b79dl66idl8sc","title":"Google DeepMind 模型免重训适配实验","summary":"该模型还能在无需重新训练的情况下即时适配实验室实验。\n\n研究人员只需接入几十个细胞的数据，就能观察 DNA 变化在特定时刻的表现，例如：\n🔘 免疫细胞对疫苗的响应\n🔘 肠道中特定细胞驱动炎症性疾病\n🔘 干细胞成熟为血细胞","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-11T15:03:18.000Z","url":"https://x.com/GoogleDeepMind/status/2120532829805096970"},{"id":"qh4ajmzfzmj3okrigl02v8407","title":"Google DeepMind 发布 AlphaGenome 2，突变识别数量接近前代两倍","summary":"Google DeepMind 发布 AlphaGenome 2，模型逐个细胞类型分析组织，避免整体观察时遗漏单个细胞内部的变化。模型基于覆盖 68 种组织的 100M+ 谱 trained 训练，识别的基因开关突变数量接近上一代模型的两倍。","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-11T15:03:18.000Z","url":"https://x.com/GoogleDeepMind/status/2120532826336501822"},{"id":"bsd9wcgzb2771m1xidimwxmgj","title":"AlphaGenome 2 聚焦特定细胞解析疾病","summary":"你的心脏、大脑和免疫系统拥有相同的 DNA 序列。那么，单个字母的改变为何会影响某些细胞中的疾病，却不影响其余细胞？\n\nAlphaGenome 2 是我们的新 AI 模型，它能聚焦特定细胞，帮助科学家理解疾病的驱动因素。🧵","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-11T15:03:17.000Z","url":"https://x.com/GoogleDeepMind/status/2120532824465805749"},{"id":"wp91dm5fgirnzvh99js3vv6j2","title":"Google DeepMind 发布 AlphaGenome 2，预测基因变异对特定细胞类型的影响","summary":"Google DeepMind 发布下一代 DNA 序列模型 AlphaGenome 2，可预测 DNA 变异如何影响数百种人类细胞类型中的基因表达。模型改为条件式架构，训练数据超过 1.07 亿个单细胞样本、覆盖 68 种组织，在 TenK10K 数据集上识别的因果变异数量接近上一代的两倍（30% vs 16%），并能在不重新训练的情况下泛化到新的单细胞实验。","sourceName":"Google DeepMind：Blog（RSS）","firstParty":true,"publishedAt":"2026-11-11T15:00:15.000Z","url":"https://deepmind.google/blog/alphagenome-2-deciphering-how-cells-read-dna-to-better-understand-disease/"},{"id":"m5zqspeyyqlao73wquaxmwn9e","title":"Google DeepMind 发布 AlphaGenome 2，预测基因变异对不同细胞状态的影响","summary":"Google DeepMind 发布基因组预测模型 AlphaGenome 2，用于捕捉基因变异在不同细胞类型和状态下的差异效应。该模型基于超过 1 亿个细胞档案和 68 种组织训练，识别可改变基因表达的变异数量接近前代最优模型的两倍，还能对未见过的细胞类型做出预测并指出实验数据缺口。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T15:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031524/google-deepmind-alphagenome-2-genetic-ai-model"}]},"6644da24-0d0a-42b1-888b-7805ed5edc3a":{"publicId":"6644da24-0d0a-42b1-888b-7805ed5edc3a","title":"xAI发布Grok Bot 1.0，定位团队AI队友","status":"active","sourceCount":9,"reportCount":11,"firstReportAt":"2026-11-11T18:22:30.000Z","latestAt":"2026-11-12T16:55:56.000Z","latest":"Grok 员工称 Grok @bot 不只是个人智能体，而是可交办完整工作流的队友","digest":"xAI 发布 Grok Bot 1.0，将其定位为可与整个团队协作的 AI 智能体队友。据 Grok Bot 官方账号称，用户可以分享 Bot，在 Slack 和 Teams 中与它们协作，邀请它们参加会议，并观察它们逐步学习、变得更高效；该账号还称已在会计、支持、销售、营销等领域把 Bot 当作团队成员使用。马斯克转发推荐把 Grok @Bot 当同事雇用、交给它最难的任务。\n\n参与该产品工程的 Lingxi Li 表示，Grok Bot 1.0 当天陆续向 ultra、team 和 enterprise 用户推出，并征集 bug 反馈；他随后称可以邀请 bot 参加会议。另一位参与者 baltaaazr 称自己参与开发，并分享把 bot 加入会议以整理信息的用法。参与 Grok Bot 的 Roshan Sadanani 称“智能体即同事”是核心设计理念，并认为 1.0 是协作方式的转折点。\n\nGrok 员工 Eric Zakariasson 进一步澄清，人们以为 Grok @bot 只是个人智能体，但它更像员工、同事和队友，可以把完整工作流端到端地交给它处理。上述功能与使用效果均来自发布方及参与者的说法。","digestUpdatedAt":"2026-11-12T17:15:24.935Z","reports":[{"id":"wrlmq8k1dje2q140fun2x8son","title":"Grok 员工称 Grok @bot 不只是个人智能体，而是可交办完整工作流的队友","summary":"Eric Zakariasson 在引用 Grok Bot 1.0 发布推文时澄清，人们以为 grok @bot 只是个人智能体，但它更像是员工、同事和队友，可以把完整工作流端到端地交给它处理。原发布称 Grok Bot 1.0 是可与全团队协作的 AI 队友，支持共享 Bot、在 Slack 和 Teams 中协作以及邀请其参加会议。","sourceName":"X：Eric Zakariasson (@ericzakariasson)","firstParty":false,"publishedAt":"2026-11-12T16:55:56.000Z","url":"https://x.com/ericzakariasson/status/2120923560177029246"},{"id":"crzwu8fwzy69uulca0wox1xna","title":"Cursor 推出 Bot 1.0","summary":"Bot 1.0 发布了！","sourceName":"X：Michael Truell (@mntruell)","firstParty":false,"publishedAt":"2026-11-12T04:31:18.000Z","url":"https://x.com/mntruell/status/2120736167385788749"},{"id":"i5tggsk133rka0syubwfflu50","title":"xAI 发布 Grok Bot 1.0","summary":"1.0","sourceName":"X：Lauren Tan（SpaceXSI，Grok Bot 工程负责人） (@poteto)","firstParty":false,"publishedAt":"2026-11-11T23:28:28.000Z","url":"https://x.com/poteto/status/2120659959465783553"},{"id":"hk6d6h4vtt5y9nr0wsgw6urz4","title":"Grok Bot 1.0 发布，定位可协作的 AI 团队成员","summary":"Roshan Sadanani 转发并评论 Grok Bot 1.0 发布，称“智能体即同事”是 Grok Bot 的核心设计理念，并认为 1.0 是协作方式的转折点。Grok Bot 支持 sharing Bots、在 Slack 和 Teams 中协作、邀请其参加 meeting，并随使用不断学习变得更有帮助。","sourceName":"X：Roshan Sadanani（SpaceXSI，Grok Bot） (@roshan_s)","firstParty":false,"publishedAt":"2026-11-11T21:07:34.000Z","url":"https://x.com/roshan_s/status/2120624499716673617"},{"id":"g4uoaazvvrtxw1nx4sj6rjsqj","title":"Grok Bot 1.0 发布：可加入会议的 AI 团队协作助手","summary":"Grok Bot 1.0 发布，定位为可与整个团队协作的 AI 队友，支持分享 Bot、在 Slack 和 Teams 中协作以及邀请其参加会�议。作者 Balta 表示自己参与开发，并分享了他把 bot 加入会议以更好整理信息、避免会议内容被遗忘的用法。","sourceName":"X：baltaaazr（SpaceXSI，Grok Bot 初版作者之一） (@baltaaazr)","firstParty":false,"publishedAt":"2026-11-11T19:22:08.000Z","url":"https://x.com/baltaaazr/status/2120597964733497612"},{"id":"dwqkdaqhef1t94venficxco9a","title":"Grok Bot 1.0 可邀入会议","summary":"是时候邀请你的 bot 参加你的会议了。有任何反馈请告诉我们！！","sourceName":"X：Lingxi Li（SpaceXSI，Grok Bot 工程） (@lingxi)","firstParty":false,"publishedAt":"2026-11-11T18:37:00.000Z","url":"https://x.com/lingxi/status/2120586605614498301"},{"id":"wwidej7vdvjn5ssmx00b8dqln","title":"xAI Grok Bot 工程参与者介绍 Grok Bot 1.0 上线","summary":"Lingxi Li 转发并介绍 Grok Bot 1.0：AI 队友可与整个团队协作，支持共享 Bots、在 Slack 和 Teams 中协作、邀请其参加会议并持续学习变得更有帮助。作者表示与 @baltaaazr 一起打造了该产品，当天陆续向 ultra、team 和 enterprise 用户推出，并征集 bug 反馈。","sourceName":"X：Lingxi Li（SpaceXSI，Grok Bot 工程） (@lingxi)","firstParty":false,"publishedAt":"2026-11-11T18:31:51.000Z","url":"https://x.com/lingxi/status/2120585312716120573"},{"id":"w8qsyyt7asblhn0mmhm5e1e86","title":"Grok Bot 1.0 发布","summary":"推出 Grok Bot 1.0。\n\nBot 可以共享，协作性和能力都前所未有地增强。","sourceName":"X：SpaceX Super Intelligence (@SpaceXSI)","firstParty":false,"publishedAt":"2026-11-11T18:30:20.000Z","url":"https://x.com/SpaceXSI/status/2120584928983441826"},{"id":"dw5s12m4xi6ru356wieday3nn","title":"马斯克宣传 Grok Bot 1.0 AI 同事，可接入 Slack 和 Teams 协作","summary":"马斯克转发并推荐把 Grok @Bot 当同事雇用、交给它最难的任务。被引用内容介绍 Grok Bot 1.0 是可随团队协作的 AI 队友，支持分享 Bot、在 Slack 和 Teams 中协作、邀请其参加会议，并随使用变得更聪明。","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-11T18:28:46.000Z","url":"https://x.com/elonmusk/status/2120584535423565889"},{"id":"yl9gdujoqcqyf76ih8c75nnx3","title":"Grok Bot 1.0 发布，主打团队协作的 AI 智能体队友","summary":"Grok Bot 发布 1.0 版本，定位为能与整个团队协作的 AI 智能体队友。用户可以分享 Bot，在 Slack 和 Teams 中与它们协作，邀请它们参加会议，并观察它们逐步学习、变得更高效。","sourceName":"X：Grok Bot (@bot)","firstParty":false,"publishedAt":"2026-11-11T18:22:30.000Z","url":"https://x.com/bot/status/2120582957782200586"},{"id":"yo20qsgpnqo08afpzfjsb1c5c","title":"Grok Bot 已作为团队队友投入使用","summary":"我们已经在把 Bot 当作团队成员使用，让它们负责会计、支持、销售、营销等领域的成果。\n\n了解所有新内容：https://x.ai/news/grok-bot-1-0","sourceName":"X：Grok Bot (@bot)","firstParty":false,"publishedAt":"2026-11-11T18:22:30.000Z","url":"https://x.com/bot/status/2120582959275426253"}]}}};
